function showBanner(index,animate=true){bannerIndex=(index+bannerSlides.length)%bannerSlides.length;const el=document.querySelector('.banner-carousel'),img=el?.querySelector('.hero-slide img');if(!el||!img)return;const slide=bannerSlides[bannerIndex],cta=el.querySelector('.hero-slide'),update=()=>{img.src=slide.src;img.alt=slide.alt;cta.dataset.bannerAction=slide.action;cta.setAttribute('aria-label',slide.alt);el.dataset.slide=bannerIndex;el.querySelectorAll('.hero-dots button').forEach((b,i)=>b.setAttribute('aria-current',String(i===bannerIndex)));requestAnimationFrame(()=>el.classList.remove('changing'))};if(animate){el.classList.add('changing');clearTimeout(showBanner.timeout);showBanner.timeout=setTimeout(update,130)}else update()}function startBannerTimer(){clearInterval(bannerTimer);if(view==='home'&&!window.matchMedia('(prefers-reduced-motion: reduce)').matches&&!bannerPaused)bannerTimer=setInterval(()=>showBanner(bannerIndex+1),30000)}
function sellerSettingsPage(){if(data.current?.role!=='seller')return '<main class="wrap"><div class="empty">Acesso exclusivo para estabelecimentos.</div></main>';view='seller';tab='settings';return seller()}function simpleArea(title,subtitle,type){
 if(type==='notifications'){let ns=visibleNotifications();return `<main class="wrap"><div class="view-title"><div><h1>${title}</h1><p>${subtitle}</p></div>${ns.some(n=>!n.read)?'<button class="btn outline" data-read-all>Marcar todas como lidas</button>':''}</div>${ns.length?ns.map(n=>`<article class="history-card ${n.read?'':'unread'}"><strong>${esc(n.title)}</strong><p>${esc(n.text)}</p><small>${new Date(n.created).toLocaleString('pt-BR')}</small>${n.read?'':' <button class="text-btn" data-read="'+n.id+'">Marcar como lida</button>'}</article>`).join(''):'<div class="empty">Nenhuma notificação por enquanto.</div>'}</main>${footer()}`}
 if(type==='conversations'){let mine=(data.conversations||[]).filter(c=>data.current?.role==='seller'?c.storeId===data.current.storeId:c.email===data.current?.email).sort((a,b)=>(b.updated||0)-(a.updated||0)),choices=data.stores.map(s=>`<option value="${s.id}">${esc(s.name)}</option>`).join('');let changed=false;return `<main class="wrap"><h1>${title}</h1><p>${subtitle} ${commercial?'Mensagens persistidas no servidor.':'As mensagens ficam salvas neste navegador.'}</p>${data.current?.role==='customer'?`<form class="form inline-form" id="conversation-start"><div class="field"><label>ESTABELECIMENTO</label><select name="storeId" required>${choices}</select></div><button class="btn">Abrir conversa</button></form>`:''}${mine.map(c=>{let unread=(c.messages||[]).filter(m=>m.unreadFor===data.current?.role).length,store=data.stores.find(s=>s.id===c.storeId);return `<article class="dash-card"><div class="dash-card-head"><strong>${data.current?.role==='seller'?esc(c.customer||c.email):esc(store?.name||'Estabelecimento')}</strong>${unread?`<span class="badge">${unread} não lida(s)</span><button class="text-btn" data-chat-read="${c.id}">Marcar como lida</button>`:''}</div><div class="dash-card-body conversation-messages">${(c.messages||[]).map(m=>`<div class="chat-message ${m.role===data.current?.role?'sent':'received'}"><b>${esc(m.author)}</b><p>${esc(m.text)}</p><small>${new Date(m.created||Date.now()).toLocaleString('pt-BR')}</small></div>`).join('')||'<p class="section-sub">Inicie a conversa com uma mensagem.</p>'}<form class="form" data-conversation="${c.id}"><input name="message" required maxlength="1000" placeholder="Escreva uma mensagem"><button class="btn">Enviar</button></form></div></article>`}).join('')||'<div class="empty">Você ainda não possui conversas.</div>'}</main>${footer()}`}
 let prefs=data.preferences?.[data.current?.email]||{};return `<main class="wrap"><h1>${title}</h1><p>${subtitle}</p><section class="dash-card"><div class="dash-card-body"><h2>Conta</h2>${data.current?`<p>${esc(data.current.name)} · ${esc(data.current.email)}</p><button class="btn" data-action="edit-account">Editar informações</button><button class="btn outline" data-action="change-password">Alterar senha</button><button class="btn outline" data-action="logout">Sair da conta</button>`:'<button class="btn" data-action="auth">Entrar</button>'}<h2>Notificações</h2><label><input type="checkbox" data-pref="notifications" ${prefs.notifications===false?'':'checked'}> Receber atualizações de pedidos e mensagens</label><h2>Privacidade, segurança e termos</h2><p><a href="#" data-view="privacy">Política de Privacidade</a> · <button class="text-btn" data-action="terms">Termos de uso</button></p><p>${commercial?'A sessão é mantida pelo provedor e dados comerciais ficam no servidor.':'O acesso neste protótipo fica armazenado localmente no navegador.'}</p></div></section></main>${footer()}`
}

function ordersPage(){if(!data.current)return '<main class="wrap"><div class="empty"><h1>Entre para acompanhar seus pedidos</h1><button class="btn" data-action="auth">Entrar</button></div></main>';if(data.current?.role==='seller'){view='seller';tab='orders';return seller()}let orders=data.orders.filter(o=>o.email===data.current?.email).filter(o=>orderScope==='all'||orderScope==='active'&&!['Entregue','Retirado','Cancelado','Recusado'].includes(o.status)||orderScope==='done'&&['Entregue','Retirado','Servido'].includes(o.status)||orderScope==='cancelled'&&['Cancelado','Recusado'].includes(o.status)).sort((a,b)=>b.created-a.created);return `<main class="wrap"><h1>Meus pedidos</h1><div class="filters">${[['all','Todos'],['active','Em andamento'],['done','Concluídos'],['cancelled','Cancelados / recusados']].map(([id,label])=>'<button class="pill '+(orderScope===id?'active':'')+'" data-order-scope="'+id+'">'+label+'</button>').join('')}</div>${orders.map(o=>history(o,true)).join('')||'<div class="empty">Você ainda não fez pedidos.</div>'}</main>${footer()}`}
function destroyDeliveryMap(){if(deliveryMap){deliveryMap.off();deliveryMap.remove();deliveryMap=null}}
function openAddressPicker(fromCheckout=true){addressForCheckout=fromCheckout;if(fromCheckout)addressOriginView=view;deliveryCoordinates=data.current?.addressCoordinates?{lat:+data.current.addressCoordinates.lat,lng:+data.current.addressCoordinates.lng}:{lat:-15.743889,lng:-43.024722};deliveryAddress=data.current?.addressDetails?.street||'';if(data.current?.addressDetails?.number)deliveryAddress+=', '+data.current.addressDetails.number;view='address';render()}
function addressPage(){return `<main class="delivery-page"><div class="delivery-heading"><button class="back" data-action="back-to-cart">← Voltar ${addressForCheckout?'ao carrinho':'ao perfil'}</button><div><span class="eyebrow">ENDEREÇO DE ENTREGA</span><h1>Escolha o ponto de entrega</h1><p>Arraste o mapa até o local exato. O pino no centro marca o destino.</p></div></div><div class="delivery-map-wrap"><div id="delivery-map" role="application" aria-label="Mapa interativo para escolher o endereço de entrega"></div><div class="delivery-pin" aria-hidden="true"><svg viewBox="0 0 40 52"><path d="M20 1C9.5 1 1 9.5 1 20c0 14 19 31 19 31s19-17 19-31C39 9.5 30.5 1 20 1Z"/><circle cx="20" cy="20" r="6"/></svg></div><button class="btn outline delivery-locate" data-action="use-location"><span aria-hidden="true">◎</span> Usar minha localização</button><div class="map-status" id="delivery-map-status" role="status">Carregando mapa…</div></div><section class="delivery-selection"><div><span class="eyebrow">LOCALIZAÇÃO SELECIONADA</span><strong id="delivery-address-preview">${esc(deliveryAddress||'Endereço aproximado ainda não consultado')}</strong><small id="delivery-coordinates">${deliveryCoordinates?`${deliveryCoordinates.lat.toFixed(5)}, ${deliveryCoordinates.lng.toFixed(5)}`:'Centro de Porteirinha, MG'}</small><button class="text-btn delivery-geocode" data-action="lookup-delivery-address">Identificar endereço no mapa</button></div><button class="btn delivery-confirm" data-action="confirm-delivery-address">Confirmar endereço de entrega</button></section><button class="btn outline" data-new-address>Adicionar endereço manual</button><p class="delivery-attribution-note">O endereço é aproximado conforme os dados disponíveis no OpenStreetMap. Confira número e complemento antes de continuar.</p></main>`}
function initDeliveryMap(){const el=document.getElementById('delivery-map');if(!el)return;if(!window.L){const status=document.getElementById('delivery-map-status');if(status)status.textContent='Mapa indisponível. Use Adicionar endereço manual para continuar.';return}if(deliveryMap){deliveryMap.remove();deliveryMap=null}const initial=deliveryCoordinates||data.current?.addressCoordinates||{lat:-15.743889,lng:-43.024722};deliveryCoordinates={lat:Number(initial.lat),lng:Number(initial.lng)};deliveryMap=L.map(el,{zoomControl:true,scrollWheelZoom:true,tap:true}).setView([deliveryCoordinates.lat,deliveryCoordinates.lng],16);L.tileLayer('https://tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:19,attribution:'&copy; <a href="https://www.openstreetmap.org/copyright" target="_blank" rel="noopener">OpenStreetMap contributors</a>'}).addTo(deliveryMap);deliveryMap.on('moveend',()=>{const p=deliveryMap.getCenter();deliveryAddress='';updateDeliveryPoint({lat:p.lat,lng:p.lng})});deliveryMap.on('tileerror',()=>{const status=document.getElementById('delivery-map-status');if(status)status.textContent='Alguns trechos do mapa não carregaram. Você ainda pode mover o mapa.'});setTimeout(()=>{deliveryMap?.invalidateSize();const p=deliveryMap?.getCenter();if(p)updateDeliveryPoint({lat:p.lat,lng:p.lng})},100)}
function updateDeliveryPoint(coords){deliveryCoordinates={lat:coords.lat,lng:coords.lng};const preview=document.getElementById('delivery-address-preview'),coordsEl=document.getElementById('delivery-coordinates'),status=document.getElementById('delivery-map-status');if(coordsEl)coordsEl.textContent=`${coords.lat.toFixed(5)}, ${coords.lng.toFixed(5)}`;if(preview)preview.textContent=deliveryAddress||'Ponto escolhido. Identifique o endereço para conferir.';if(status)status.textContent='Mova o mapa para ajustar o pino central ou identifique o endereço.'}
function lookupDeliveryAddress(coords){const key=`${coords.lat.toFixed(5)},${coords.lng.toFixed(5)}`,show=(address,message)=>{const current=deliveryMap?.getCenter(),stillSelected=current&&`${current.lat.toFixed(5)},${current.lng.toFixed(5)}`===key;if(stillSelected){deliveryAddress=address;const p=document.getElementById('delivery-address-preview'),status=document.getElementById('delivery-map-status');if(p)p.textContent=address||'Endereço não localizado automaticamente. Você poderá digitá-lo na próxima etapa.';if(status)status.textContent=message}return address};if(deliveryGeocodeCache[key])return Promise.resolve(show(deliveryGeocodeCache[key],'Endereço encontrado. Confira os detalhes antes de confirmar.'));const task=geocodeQueue.then(async()=>{const wait=Math.max(0,1100-(Date.now()-lastGeocodeAt));if(wait)await new Promise(resolve=>setTimeout(resolve,wait));lastGeocodeAt=Date.now();try{const url=`https://nominatim.openstreetmap.org/reverse?format=jsonv2&lat=${encodeURIComponent(coords.lat)}&lon=${encodeURIComponent(coords.lng)}&zoom=18&addressdetails=1`;const response=await fetch(url,{headers:{'Accept':'application/json','Accept-Language':'pt-BR,pt;q=0.9'}});if(!response.ok)throw new Error('reverse geocoding unavailable');const result=await response.json();if(!result?.display_name)throw new Error('address not found');deliveryGeocodeCache[key]=result.display_name;return show(result.display_name,'Endereço encontrado. Confira os detalhes antes de confirmar.')}catch{return show('','Geocodificação indisponível; o pino e as coordenadas foram mantidos.')}});geocodeQueue=task.then(()=>undefined,()=>undefined);return task}
function useDeliveryLocation(){const status=document.getElementById('delivery-map-status');if(!navigator.geolocation){if(status)status.textContent='Este navegador não oferece localização. Mova o mapa manualmente.';return toast('GPS indisponível. Você pode mover o mapa manualmente.')}if(status)status.textContent='Obtendo sua localização…';navigator.geolocation.getCurrentPosition(pos=>{const coords={lat:pos.coords.latitude,lng:pos.coords.longitude};deliveryCoordinates=coords;deliveryAddress='';deliveryMap?.setView([coords.lat,coords.lng],18);updateDeliveryPoint(coords);if(status)status.textContent='Localização encontrada. Ajuste o mapa se necessário.'},err=>{if(status)status.textContent=err.code===1?'Permissão de localização negada. Mova o mapa manualmente.':'Não foi possível obter o GPS. Mova o mapa manualmente.';toast('Não foi possível usar o GPS. O mapa continua disponível.')},{enableHighAccuracy:true,timeout:12000,maximumAge:30000})}
async function confirmDeliveryAddress(){if(!deliveryMap)return toast('O mapa ainda está carregando.');const p=deliveryMap.getCenter(),coords={lat:p.lat,lng:p.lng};deliveryCoordinates=coords;let resolvedAddress=deliveryAddress;if(!resolvedAddress)resolvedAddress=await lookupDeliveryAddress(coords);if(!deliveryMap)return;const current=deliveryMap.getCenter();if(current.lat.toFixed(5)!==coords.lat.toFixed(5)||current.lng.toFixed(5)!==coords.lng.toFixed(5))return toast('O mapa foi movido. Confirme novamente o ponto selecionado.');const a=data.current?.addressDetails||{};modal(`<div class="modal-head"><div><h2>Detalhes do endereço</h2><p>${esc(resolvedAddress||'Informe a rua ou o endereço para esta localização')}</p><small>Coordenadas: ${coords.lat.toFixed(6)}, ${coords.lng.toFixed(6)}</small></div><button class="close" data-action="close-modal">×</button></div><form id="delivery-address-form" class="form"><div class="field"><label>RUA / ENDEREÇO</label><input name="street" required maxlength="180" value="${esc(a.street||resolvedAddress)}" placeholder="Endereço encontrado no mapa"></div><div class="field"><label>NÚMERO</label><input name="number" required maxlength="30" value="${esc(a.number||'')}" placeholder="Número do imóvel"></div><div class="field"><label>COMPLEMENTO</label><input name="complement" maxlength="100" value="${esc(a.complement||'')}" placeholder="Apartamento, bloco, casa... (opcional)"></div><div class="field"><label>PONTO DE REFERÊNCIA</label><input name="reference" maxlength="120" value="${esc(a.reference||'')}" placeholder="Portão, comércio próximo... (opcional)"></div><button class="btn">Salvar endereço e continuar</button></form>`)}
function showCheckoutPayment(){const s=cartStore(),sub=cartSubtotal();if(!s||!data.cart.length)return toast('Carrinho vazio.');if(fulfillment==='pickup'&&(!s.pickupEnabled||!s.address))return toast('Retirada indisponível nesta loja.');const fee=fulfillment!=='delivery'?0:commercial?commercialDeliveryFee(s):storeDeliveryFee(s),its=data.cart.map(r=>{const p=products().find(p=>p.id===r.pid);return {...p,...r,price:(p?.price||0)+(r.extras||[]).reduce((n,x)=>n+Number(x.price||0),0)}});if(fee===null)return toast(s.deliveryEnabled===false?'Esta loja não oferece entrega. Escolha retirada, quando disponível.':'Este endereço não é atendido pela loja. Escolha outro endereço ou retirada.');if(sub<(Number(s.minimumOrder)||0))return toast('Pedido mínimo: '+money(s.minimumOrder));modal('<div class="modal-head"><div><h2>Revisar pedido</h2><p>'+esc(s.name)+'</p></div><button class="close" data-action="close-modal">×</button></div>'+localNotice()+orderItems(its)+'<div class="checkout-address-summary"><b>'+(fulfillment==='dine_in'?'Pedido presencial · '+esc(window.NortFoodQR?.mode(s)?.label):fulfillment==='pickup'?'Retirada no estabelecimento':'Endereço de entrega')+'</b><p>'+esc(fulfillment==='dine_in'?'Atendimento no estabelecimento':fulfillment==='pickup'?s.address:data.current.address)+'</p><button class="text-btn" type="button" data-fulfillment="delivery">Escolher endereço de entrega</button>'+(s.pickupEnabled&&s.address?'<button class="text-btn" type="button" data-fulfillment="pickup">Retirar na loja · sem taxa de entrega</button>':'')+(fulfillment==='pickup'?window.NortFoodLocation.summary(s,s.name,'Como chegar para retirar'):'')+'</div><form class="form" id="checkout-form" data-reviewed-total="'+Math.round((sub+fee)*100)+'"><div class="field"><label for="checkout-payment">Pagamento na entrega ou retirada</label><select id="checkout-payment" name="payment">'+(s.acceptedPayments?.length?s.acceptedPayments:['Pix na entrega','Dinheiro na entrega','Cartão na entrega']).map(p=>'<option>'+esc(p)+'</option>').join('')+'</select></div><div class="field"><label for="checkout-notes">Observação (opcional)</label><input id="checkout-notes" name="notes" maxlength="300"></div><div class="total-line"><span>Produtos</span><b>'+money(sub)+'</b></div><div class="total-line"><span>'+(fulfillment==='dine_in'?'Atendimento na mesa':fulfillment==='pickup'?'Retirada':'Entrega')+'</span><b>'+money(fee)+'</b></div><div class="total-line final"><span>Total</span><b>'+money(sub+fee)+'</b></div><p>Entrega realizada pela loja. O pagamento não é processado pelo NortFood.</p><button class="btn">'+(commercial?'Confirmar pedido':'Confirmar pedido demonstrativo')+'</button></form>');window.NortFoodSite?.track('begin_checkout',s.id+':'+sub+':'+fulfillment)}

function mapPage(){return '<main class="wrap"><h1>Localização dos estabelecimentos</h1><p>Posições e endereços cadastrados pelas lojas. A rota abre no Google Maps.</p>'+data.stores.filter(s=>!commercial||s.status==='approved').map(s=>'<article class="dash-card"><div class="dash-card-body"><h2>'+esc(s.name)+'</h2>'+window.NortFoodLocation.summary(s,s.name)+'<button class="btn soft" data-open="'+esc(s.id)+'">Ver estabelecimento</button></div></article>').join('')+'</main>'+footer()}
function privacyPage(){return `<main class="wrap legal"><h1>Política de Privacidade</h1><p>Última atualização: 3 de outubro de 2026</p><p>Esta página apresenta informações preliminares sobre o protótipo NortFood e deve ser revisada juridicamente antes de uso comercial.</p><h2>Dados neste protótipo</h2><p>Informações de conta, lojas, pedidos, conversas, endereços e coordenadas podem ser armazenadas no armazenamento local do navegador. Pessoas com acesso ao mesmo dispositivo e navegador podem consultar esses dados.</p><h2>Uso e compartilhamento</h2><p>O mapa carrega os blocos do OpenStreetMap. Os estabelecimentos podem confirmar uma posição fixa, exibida aos clientes. Abrir Como chegar não captura a localização do cliente; a navegação abre no Google Maps. Ao pedir a identificação automática do endereço de entrega, as coordenadas escolhidas são consultadas no serviço público Nominatim do OpenStreetMap. Pedidos e mensagens permanecem neste navegador e não são enviados ao estabelecimento por um servidor nesta versão. O cadastro e a autenticação são demonstrativos e não oferecem segurança de produção. Não informe senhas ou dados sensíveis reais.</p><h2>Contato e revisão</h2><p>Os meios de contato, prazos de retenção, bases legais, direitos dos titulares e responsáveis pelo tratamento ainda precisam ser definidos pela operação do NortFood.</p><p>Este texto não substitui uma política revisada por profissional jurídico.</p></main>${footer()}`}function closeCart(){document.querySelector('.drawer')?.remove();document.querySelector('.drawer-scrim')?.remove()}function closeModal(){window.NortFoodLocation?.dispose(document.querySelector('.modal-scrim')||document.createElement('div'));const had=!!document.querySelector('.modal-scrim');document.querySelector('.modal-scrim')?.remove();if(had&&overlayFocus?.isConnected)overlayFocus.focus()}function modal(html){closeModal();document.body.insertAdjacentHTML('beforeend',`<div class="modal-scrim" data-action="scrim"><section class="modal">${html}</section></div>`);focusOverlay();prepareCommercialForms()}function notFoundPage(){return '<main class="wrap standalone-error"><p class="eyebrow">PÁGINA NÃO ENCONTRADA · 404</p><h1>Esta página não está disponível.</h1><p>Confira o link ou volte para encontrar os estabelecimentos.</p><button class="btn" data-view="home">Voltar ao NortFood</button></main>'}
function render(){window.NortFoodLocation?.dispose();closeCart();closeModal();const page=view==='admin'&&commercial?commercialController?.adminPage()||'<main class="wrap">Carregando administração…</main>':view==='search'?discoveryPage():view==='favorites'?favoritesPage():view==='offers'?offersPage():view==='help'?helpPage():view==='addresses'?addressBookPage():view==='order-detail'?orderDetailPage():view==='shop'?shop():view==='address'?addressPage():view==='profile'?profile():view==='seller'?seller():view==='seller-settings'?sellerSettingsPage():view==='conversations'?simpleArea('Conversas','Mensagens entre clientes e estabelecimentos.','conversations'):view==='notifications'?simpleArea('Notificações','Atualizações dos seus pedidos e da sua conta.','notifications'):view==='settings'?simpleArea('Configurações','Preferências da sua conta NortFood.','settings'):view==='legal'?commercialLegal():view==='privacy'?(commercial?commercialLegal():privacyPage()):view==='map'?mapPage():view==='orders'?ordersPage():view==='not-found'?notFoundPage():home();app.innerHTML=header()+(commercial?commercialBanner():'')+page+(view==='address'?'':navigation());if(view==='address')initDeliveryMap();else destroyDeliveryMap();startBannerTimer();syncRoute();commercialDecorate();prepareCommercialForms();window.NortFoodSite?.refresh()}
function cart(){if(!document.querySelector('.drawer'))document.body.insertAdjacentHTML('beforeend','<div class="drawer-scrim" data-action="close-cart"></div><aside class="drawer"><div class="drawer-head"><h2>Seu carrinho</h2><button class="close" data-action="close-cart">×</button></div><div class="drawer-body" id="cartbody"></div><div id="cartfoot"></div></aside>');drawCart();focusOverlay()}
function drawCart(){let b=document.getElementById('cartbody'),f=document.getElementById('cartfoot');if(!b)return;let its=data.cart.map((r,index)=>({...products().find(p=>p.id===r.pid),...r,index})).filter(x=>x.id),sum=cartSubtotal();if(its.length){b.innerHTML=its.map(x=>`<div class="cart-item"><div><strong>${esc(x.emoji)} ${esc(x.name)}</strong><small>${money(x.price+(x.extras||[]).reduce((n,extra)=>n+(Number(extra.price)||0),0))} cada${x.extras?.length?' · '+x.extras.map(extra=>esc(extra.name)).join(', '):''}${x.note?' · '+esc(x.note):''}</small></div><div class="qty"><button aria-label="Diminuir quantidade de ${esc(x.name)}" data-qty="${x.index}" data-step="-1">−</button><b>${x.qty}</b><button aria-label="Aumentar quantidade de ${esc(x.name)}" data-qty="${x.index}" data-step="1">+</button></div></div>`).join('');f.innerHTML=`<div class="totals"><div class="total-line"><span>Subtotal</span><span>${money(sum)}</span></div><div class="total-line"><span>Entrega estimada</span><span>${deliveryFeeLabel(cartStore())}</span></div><div class="total-line final"><span>Total</span><span>${storeDeliveryFee(cartStore())===null?money(sum)+' + entrega a confirmar':money(sum+storeDeliveryFee(cartStore()))}</span></div></div><button class="btn" data-action="checkout">Continuar pedido →</button>`}else{b.innerHTML='<div class="empty"><div class="big">🛍️</div>Seu carrinho está esperando algo gostoso.</div>';f.innerHTML=''}let c=document.querySelector('.cart-count');if(c)c.textContent=data.cart.reduce((n,x)=>n+x.qty,0)}
function auth(){if(data.current){view='profile';render();return}authMode='register';authRole='customer';authForm()}
function loginIcon(name){const icons={mail:'<rect x="3" y="5" width="18" height="14" rx="2"/><path d="m4 7 8 6 8-6"/>',lock:'<rect x="4" y="10" width="16" height="11" rx="2"/><path d="M8 10V7a4 4 0 0 1 8 0v3"/>',eye:'<path d="M2 12s3.5-6 10-6 10 6 10 6-3.5 6-10 6-10-6-10-6Z"/><circle cx="12" cy="12" r="2.5"/>',eyeOff:'<path d="m3 3 18 18M10.6 6.1A10.7 10.7 0 0 1 12 6c6.5 0 10 6 10 6a15 15 0 0 1-3 3.7M6.2 6.8C3.5 8.5 2 12 2 12s3.5 6 10 6c1 0 1.9-.1 2.8-.4"/><path d="M9.9 9.9a3 3 0 0 0 4.2 4.2"/>',arrow:'<path d="M5 12h14M13 6l6 6-6 6"/>'};return `<svg class="auth-icon auth-icon-${name}" viewBox="0 0 24 24" aria-hidden="true" focusable="false" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round">${icons[name]||icons.mail}</svg>`}
function showPasswordForm(recovery=false){modal(`<div class="modal-head"><h2>${recovery?'Definir nova senha':'Alterar senha'}</h2><button class="close" data-action="close-modal">×</button></div><form id="password-form" class="form"><div class="field"><label>SENHA ATUAL</label><input name="currentPassword" type="password" required></div><div class="field"><label>NOVA SENHA</label><input name="newPassword" type="password" minlength="4" required></div><div class="field"><label>CONFIRMAR NOVA SENHA</label><input name="confirmPassword" type="password" minlength="4" required></div><button class="btn">Salvar senha</button></form>`);}
function showRecovery(){if(!document.getElementById('password-form'))showPasswordForm(true);}
function authConfirmation(email){modal('<div data-auth-confirmation role="status" aria-live="polite"><div class="modal-head"><h2>Confirme seu e-mail</h2><button class="close" data-action="close-modal" aria-label="Fechar confirmação">×</button></div><p>Confira a caixa de entrada e o spam de <strong>'+esc(email)+'</strong>.</p><p>Abra o link enviado para confirmar o acesso. Ao retornar neste navegador com uma sessão válida, você entrará automaticamente, sem digitar a senha novamente.</p><p>A conta ainda não está conectada. Não recebeu o e-mail? Aguarde alguns minutos e confira o endereço informado.</p><button class="btn outline" data-auth-mode="login">Já confirmei — Entrar</button></div>');}
function authForm(){if(commercial&&window.NORTFOOD_CONFIG?.publicPreview){modal('<div class="modal-head"><h2>NortFood em preparação</h2><button class="close" data-action="close-modal" aria-label="Fechar">×</button></div><p>Estamos preparando as lojas e validando a operação. Cadastros e pedidos comerciais ainda não foram liberados.</p><p>Volte em breve para acompanhar as novidades.</p><button class="btn" data-action="close-modal">Entendi</button>');return;}const registering=authMode==='register';modal(`<div class="auth-brand">${brandLogo('auth-logo')}<button class="close" type="button" data-action="close-modal" aria-label="Fechar login">×</button></div><div class="auth-intro"><span class="eyebrow">${authRole==='seller'?'ÁREA DO ESTABELECIMENTO':'SABORES DO SEU BAIRRO'}</span><h2>${registering?'Crie sua conta':'Bem-vindo de volta'}</h2><p>${registering?'Cadastre-se para continuar no NortFood.':'Entre para continuar no NortFood.'}</p></div><div class="switch auth-role-switch" aria-label="Tipo de conta"><button type="button" class="${authRole==='customer'?'active':''}" data-role="customer" aria-pressed="${authRole==='customer'}">Cliente</button><button type="button" class="${authRole==='seller'?'active':''}" data-role="seller" aria-pressed="${authRole==='seller'}">Estabelecimento</button></div><form class="form auth-form" id="auth-form" novalidate>${registering?`<div class="field"><label for="auth-name">${authRole==='seller'?'Seu nome':'Nome completo'}</label><input id="auth-name" name="name" required autocomplete="name" placeholder="Como podemos chamar você?"></div>${authRole==='seller'?'<div class="field"><label for="auth-store-name">Nome do estabelecimento</label><input id="auth-store-name" name="storeName" required autocomplete="organization" placeholder="Nome da sua loja"></div>':''}`:''}<div class="field"><label for="auth-email">E-mail ou telefone</label><div class="auth-input-wrap">${loginIcon('mail')}<input id="auth-email" type="text" name="identifier" required autocomplete="username" inputmode="text" placeholder="voce@email.com ou (38) 99999-9999"></div></div>${registering?'<div class="field"><label for="auth-phone">Telefone (opcional)</label><input id="auth-phone" name="phone" type="tel" autocomplete="tel" inputmode="tel" placeholder="(38) 99999-9999"></div><label class="consent"><input type="checkbox" name="consent" required> Li e concordo com a <a href="#" data-view="privacy">Política de Privacidade</a> e os termos aplicáveis ao cadastro.</label>':''}<div class="field"><div class="auth-label-row"><label for="auth-password">Senha</label>${registering?'':'<span class="auth-unavailable" title="Recuperação de senha ainda não configurada">Esqueci minha senha</span>'}</div><div class="auth-input-wrap">${loginIcon('lock')}<input id="auth-password" type="password" name="password" required minlength="4" autocomplete="${registering?'new-password':'current-password'}" placeholder="${registering?'Crie uma senha':'Digite sua senha'}"><button class="auth-password-toggle" type="button" data-action="toggle-password" aria-label="Mostrar senha" aria-pressed="false">${loginIcon('eye')}</button></div></div>${registering?'':'<label class="auth-remember"><input type="checkbox" name="remember" checked><span>Lembrar de mim</span><small>Sessão mantida neste navegador</small></label>'}<p id="auth-error" class="auth-error" role="alert" aria-live="polite"></p><button class="btn auth-submit" type="submit">${registering?'Criar conta':'Entrar'} ${loginIcon('arrow')}</button></form><div class="auth-divider"><span>ou</span></div><button class="auth-google" type="button" data-action="google-auth" disabled aria-describedby="google-unavailable"><span class="google-mark" aria-hidden="true">G</span>Entrar com Google</button><small id="google-unavailable" class="auth-unavailable-note">Login com Google ainda não está configurado.</small><p class="auth-signup">${registering?'Já tenho uma conta —':'Ainda não possui uma conta?'} <button type="button" data-auth-mode="${registering?'login':'register'}">${registering?'Entrar':'Criar conta'}</button></p><p class="auth-demo-note">Acesso demonstrativo: contas e sessão ficam salvas neste navegador.</p>`);document.querySelector('.modal')?.classList.add('auth-modal')}
async function submitAuthForm(form,formData){const error=document.getElementById('auth-error'),fail=message=>{if(error)error.textContent=message;return false},identifier=String(formData.get('identifier')??formData.get('email')??'').trim(),password=String(formData.get('password')||''),registering=authMode==='register',emailCandidate=identifier.toLowerCase(),emailPattern=/^[^\s@]+@[^\s@]+\.[^\s@]+$/,phoneDigits=normalizePhone(identifier);if(error)error.textContent='';if(!identifier)return fail('Informe seu e-mail ou telefone.');if(identifier.includes('@')&&!emailPattern.test(emailCandidate))return fail('Digite um e-mail válido.');if(!identifier.includes('@')&&!validPhone(identifier))return fail('Digite um telefone válido com DDD.');if(!password)return fail('Informe sua senha.');if(registering&&password.length<4)return fail('A senha deve ter pelo menos 4 caracteres.');if(registering&&!String(formData.get('name')||'').trim())return fail('Informe seu nome.');if(registering&&authRole==='seller'&&!String(formData.get('storeName')||'').trim())return fail('Informe o nome do estabelecimento.');if(registering&&!form.querySelector('[name="consent"]')?.checked)return fail('Confirme a leitura da Política de Privacidade para criar sua conta.');const phone=registering?normalizePhone(formData.get('phone')):'',phoneInput=String(formData.get('phone')||'').trim();if(registering&&phoneInput&&!validPhone(phoneInput))return fail('Digite um telefone válido com DDD.');let user;if(registering){if(!emailPattern.test(emailCandidate))return fail('Use um e-mail válido para criar sua conta.');if(data.users.some(item=>String(item.email||'').toLowerCase()===emailCandidate||(phone&&normalizePhone(item.phone)===phone)))return fail('Este e-mail ou telefone já possui uma conta.');user={name:String(formData.get('name')).trim(),email:emailCandidate,...(phone?{phone}:{}),role:authRole,address:''};if(authRole==='seller'&&!String(formData.get('storeName')||'').trim())return fail('Informe o nome do estabelecimento.');await setPassword(user,password);const previousSession=data.current,previousRemember=rememberSession,storeIdForUser=authRole==='seller'?'loja-'+Date.now():null;if(storeIdForUser){user.storeId=storeIdForUser;data.stores.push({id:storeIdForUser,name:String(formData.get('storeName')).trim(),categories:['Lanches'],category:'Lanches',emoji:'🏪',gradient:'linear-gradient(135deg,#ef8b78,#cb3a48)',rating:5,time:'30–45 min',fee:'R$ 4,99',promo:'Novidade no NortFood',about:'Uma loja local pertinho de você.',featured:false,products:[],openOverride:null,manualStatusOverride:null,workingDays:[0,1,2,3,4,5,6],hours:'11:00-22:00',deliveryFee:4.99,minimumOrder:0,acceptedPayments:['Pix na entrega','Dinheiro na entrega','Cartão na entrega']})}data.users.push(user);data.current=user;switchCart(user.email,true);rememberSession=!!formData.get('remember');try{save()}catch{data.users=data.users.filter(item=>item!==user);if(storeIdForUser)data.stores=data.stores.filter(item=>item.id!==storeIdForUser);data.current=previousSession;rememberSession=previousRemember;return fail('Não foi possível salvar a conta ou a sessão neste navegador. Verifique o armazenamento disponível e tente novamente.')}}else{user=identifier.includes('@')?data.users.find(item=>String(item.email||'').toLowerCase()===emailCandidate):data.users.find(item=>phoneDigits&&normalizePhone(item.phone)===phoneDigits);if(!user)return fail('Não encontramos uma conta com esse e-mail ou telefone.');if(!await checkPassword(user,password))return fail('Senha incorreta. Confira seus dados e tente novamente.');if(user.role!==authRole)return fail(user.role==='seller'?'Esta conta é de estabelecimento. Selecione “Estabelecimento” para entrar.':user.role==='admin'?'Esta conta não pode acessar esta área.':'Esta conta é de cliente. Selecione “Cliente” para entrar.');if(user.role==='seller'&&!data.stores.some(store=>store.id===user.storeId))return fail('O estabelecimento desta conta não foi encontrado. Entre em contato com o suporte.');const previousSession=data.current,previousRemember=rememberSession;data.current=user;switchCart(user.email,true);rememberSession=!!formData.get('remember');try{save()}catch{data.current=previousSession;rememberSession=previousRemember;return fail('Não foi possível salvar sua sessão neste navegador. Verifique o armazenamento disponível e tente novamente.')}}closeModal();view=user.role==='seller'?'seller':'home';tab='orders';render();toast('Bem-vindo(a), '+String(user.name||'').split(' ')[0]+'!');return true}function profile(){if(!data.current)return '<main class="wrap"><div class="empty"><h1>Acesse seu perfil</h1><button class="btn" data-action="auth">Entrar ou criar conta</button></div></main>';if(data.current?.role==='seller'){let st=data.stores.find(x=>x.id===data.current.storeId);return `<main class="wrap"><div class="view-title"><h1>Conta do estabelecimento</h1><button class="btn outline small" data-action="logout">Sair</button></div><div class="profile-links"><button data-view="conversations">Conversas</button><button data-view="notifications">Notificações</button><button data-view="seller-settings">Conta comercial</button><button data-view="settings">Configurações</button><button data-view="help">Ajuda</button></div><section class="dash-card"><div class="dash-card-body"><h2>${esc(st?.name||'Estabelecimento')}</h2><p>${esc(st?.about||'')}</p><p>${esc(data.current.name)} · ${esc(data.current.email)}</p><p>${st?storeStatus(st).label:''}</p><button class="btn" data-view="seller-settings">Editar perfil comercial</button></div></section></main>${footer()}`}let u=data.current,orders=data.orders.filter(o=>o.email===u.email).sort((a,b)=>b.created-a.created);return `<main class="wrap"><div class="view-title"><h1>Minha conta</h1><button class="btn outline small" data-action="logout">Sair</button></div><div class="profile-links"><button data-view="conversations">Conversas</button><button data-view="notifications">Notificações</button><button data-view="favorites">Favoritos</button><button data-view="addresses">Endereços</button><button data-view="help">Ajuda</button><button data-action="edit-account">Conta</button><button data-view="settings">Configurações</button></div><div class="dash-card"><div class="dash-card-body"><div class="profile"><div class="avatar">${esc(u.name[0].toUpperCase())}</div><div><strong>${esc(u.name)}</strong><small>${esc(u.email)}</small></div></div><p>${u.address?'📍 '+esc(u.address):'Informe seu endereço no checkout.'}</p><button class="text-btn" data-action="edit-delivery-address">${u.address?'Editar endereço de entrega':'Adicionar endereço de entrega'}</button></div></div><div class="section-head"><div><h2>Meus pedidos</h2><p class="section-sub">Acompanhe e veja seu histórico.</p></div></div>${orders.length?orders.map(o=>history(o,true)).join(''):'<div class="empty">Você ainda não fez pedidos.<br><button class="btn soft" data-view="home">Explorar lojas</button></div>'}</main>${footer()}`}
function history(o,cancel){return `<article class="history-card"><div class="history-card-top"><strong>${o.fulfillment==='dine_in'?'Pedido presencial — '+esc(o.tableLabel)+' · ':''}Pedido #${o.id.slice(-5)} · ${esc(o.storeName)}</strong><span class="status ${o.status==='Pronto para retirada'?'ready':['Entregue','Retirado','Servido'].includes(o.status)?'completed':o.status==='Cancelado'?'cancelled':''}">${esc(o.status)}</span></div><p>${new Date(o.created).toLocaleString('pt-BR',{dateStyle:'medium',timeStyle:'short'})} · ${o.items.map(i=>i.qty+'× '+esc(i.name)).join(', ')}</p><div class="order-row"><span>${esc(o.address)} · ${esc(o.payment)}${o.reference?' · Referência: '+esc(o.reference):''}</span><b>${money(o.total)}</b>${o.addressCoordinates?`<a class="text-btn" target="_blank" rel="noopener" href="https://www.openstreetmap.org/?mlat=${o.addressCoordinates.lat}&mlon=${o.addressCoordinates.lng}#map=18/${o.addressCoordinates.lat}/${o.addressCoordinates.lng}">Ver local no mapa</a>`:''}</div><button class="btn soft small" data-order-detail="${esc(o.id)}">Ver detalhes e acompanhamento</button>${cancel&&o.status==='Recebido'?`<button class="text-btn" data-cancel="${o.id}">Cancelar pedido</button>`:''}</article>`}
function storeSettingsForm(s){
 const selected=storeCategories(s),days=s.workingDays||[0,1,2,3,4,5,6],payments=s.acceptedPayments||['Pix na entrega','Dinheiro na entrega','Cartão na entrega'];
 const categories=cats.slice(1).map(({label:name})=>`<label class="check-chip"><input type="checkbox" name="categories" value="${esc(name)}" ${selected.includes(name)?'checked':''}><span>${esc(name)}</span></label>`).join('');
 const weekday=['Dom','Seg','Ter','Qua','Qui','Sex','Sáb'].map((name,i)=>`<label class="check-chip"><input type="checkbox" name="workingDays" value="${i}" ${days.includes(i)?'checked':''}><span>${name}</span></label>`).join('');
 const paymentFields=(commercial?['Pix diretamente à loja ao receber','Dinheiro ao receber','Cartão ao receber']:['Pix na entrega','Dinheiro na entrega','Cartão na entrega']).map(name=>`<label class="check-chip"><input type="checkbox" name="payments" value="${esc(name)}" ${payments.includes(name)?'checked':''}><span>${esc(name)}</span></label>`).join('');
 return `<div class="dash-card"><div class="dash-card-head"><strong>Perfil do estabelecimento</strong><button class="btn outline small" data-open="${s.id}">Visualizar perfil</button></div><div class="dash-card-body"><form id="store-form" class="form store-settings-form">
 <div class="field"><label for="store-name">Nome do estabelecimento</label><input id="store-name" name="name" value="${esc(s.name)}" required maxlength="80"></div>
 <div class="field"><label for="store-about">Descrição</label><textarea id="store-about" name="about" maxlength="500">${esc(s.about||'')}</textarea></div>
 <fieldset class="field category-field"><legend>Categorias do estabelecimento</legend><div class="category-checks">${categories}</div></fieldset>
 <div class="form-two-columns"><div class="field"><label for="store-phone">Telefone</label><input id="store-phone" name="phone" type="tel" autocomplete="tel" value="${esc(s.phone||'')}" maxlength="30"></div><div class="field"><label for="store-whatsapp">WhatsApp</label><input id="store-whatsapp" name="whatsapp" type="tel" value="${esc(s.whatsapp||'')}" maxlength="30"></div></div>
 <div class="field"><label for="store-street">Rua / endereço</label><input id="store-street" name="street" value="${esc(s.street||s.address||'')}" maxlength="120"></div>
 <div class="form-two-columns"><div class="field"><label for="store-number">Número</label><input id="store-number" name="number" value="${esc(s.number||'')}" maxlength="20"></div><div class="field"><label for="store-complement">Complemento</label><input id="store-complement" name="complement" value="${esc(s.complement||'')}" maxlength="80"></div></div>
 <div class="form-two-columns"><div class="field"><label for="store-neighborhood">Bairro</label><input id="store-neighborhood" name="neighborhood" value="${esc(s.neighborhood||'')}" maxlength="80"></div><div class="field"><label for="store-city">Cidade</label><input id="store-city" name="city" value="${esc(s.city||'')}" maxlength="80"></div></div>
 <div class="field"><label for="store-hours">Horário diário (abertura-fechamento)</label><input id="store-hours" name="hours" pattern="(?:[01][0-9]|2[0-3]):[0-5][0-9]-(?:[01][0-9]|2[0-3]):[0-5][0-9]" placeholder="11:00-22:00" value="${esc(s.hours||'11:00-22:00')}" required></div>
 <fieldset class="field category-field"><legend>Dias de funcionamento</legend><div class="category-checks">${weekday}</div></fieldset>
 <div class="form-two-columns"><div class="field"><label for="store-delivery-fee">Taxa de entrega (R$)</label><input id="store-delivery-fee" name="deliveryFee" type="number" min="0" step="0.01" value="${(storeDeliveryFee(s)??0).toFixed(2)}" required></div><div class="field"><label for="store-delivery-time">Tempo estimado</label><input id="store-delivery-time" name="time" value="${esc(s.time||'30–45 min')}" maxlength="30" required></div></div>
 <label class="extra-choice"><input type="checkbox" name="pickupEnabled" ${s.pickupEnabled?'checked':''}> Oferecer retirada no estabelecimento (cadastre o endereço)</label>${commercial?'<label><input type="checkbox" name="deliveryEnabled" '+(s.deliveryEnabled?'checked':'')+'> Oferecer entrega pela loja</label><div class="field"><label>Bairros atendidos e taxa (bairro:valor, um por linha)</label><textarea name="zones">'+esc((s.deliveryZones||[]).map(z=>z.neighborhood+':'+(z.fee_cents/100).toFixed(2)).join('\n'))+'</textarea><small>Endereços fora desses bairros serão recusados pelo servidor.</small></div><div class="field"><label>Estimativa em minutos</label><input name="estimateMinutes" type="number" min="1" max="240" value="'+esc(s.estimateMinutes||'')+'"></div>':''}<div class="field"><label for="store-minimum">Valor mínimo do pedido (R$)</label><input id="store-minimum" name="minimumOrder" type="number" min="0" step="0.01" value="${Number(s.minimumOrder)||0}"></div>
 <fieldset class="field category-field"><legend>Formas de pagamento aceitas</legend><div class="category-checks">${paymentFields}</div></fieldset>
 <div class="field"><label for="store-pix">Chave Pix</label><input id="store-pix" name="pixKey" value="${esc(s.pixKey||'')}" maxlength="120" autocomplete="off"></div>
 <div class="field"><label for="store-delivery-info">Informações sobre a entrega</label><input id="store-delivery-info" name="deliveryInfo" value="${esc(s.deliveryInfo||'Entrega feita pelo estabelecimento')}" maxlength="180"></div>
 <div class="form-two-columns"><div class="field"><label>Logo do estabelecimento</label><input type="file" name="logo" accept="image/*"><small>Imagem local de até 1 MB.</small></div><div class="field"><label>Imagem de capa</label><input type="file" name="cover" accept="image/*"><small>Imagem local de até 1 MB.</small></div></div>
 <button type="submit" class="btn">Salvar perfil</button><button type="reset" class="btn outline">Descartar alterações</button></form><p>A entrega é responsabilidade do estabelecimento.</p></div></div>`
}

function storeDeliveryFee(s){if(commercial)return commercialDeliveryFee(s);if(s.deliveryFee!==undefined&&Number.isFinite(Number(s.deliveryFee)))return Math.max(0,Number(s.deliveryFee));if(s.fee==='Grátis')return 0;const match=String(s.fee||'').match(/[0-9]+(?:[,.][0-9]{1,2})?/);return match?Number(match[0].replace(',','.')):4.99}
function cartStore(){const first=data.cart.map(row=>products().find(product=>product.id===row.pid)).find(Boolean);return data.stores.find(store=>store.id===first?.store)}
function cartSubtotal(){if(commercial)return data.cart.reduce((sum,row)=>{const p=products().find(p=>p.id===row.pid);if(!p)return sum;return sum+(Math.round(p.price*100)+(row.extras||[]).reduce((n,e)=>n+Math.round(e.price*100),0))*row.qty},0)/100;return data.cart.reduce((sum,row)=>{const product=products().find(item=>item.id===row.pid);if(!product)return sum;const extras=(row.extras||[]).reduce((n,extra)=>n+(Number(extra.price)||0),0);return sum+(product.price+extras)*row.qty},0)}
function commissionRate(){const rate=Number(data.platformSettings?.commissionRate);return Number.isFinite(rate)&&rate>=0&&rate<=.2?rate:RATE}
function validOrderTransition(order,next,role){if(role==='customer')return order.status==='Recebido'&&next==='Cancelado';if(role!=='seller')return false;const transitions={'Recebido':['Em preparo','Recusado'],'Em preparo':['Pronto para retirada'],'Pronto para retirada':order.fulfillment==='pickup'?['Entregue']:['Em entrega'],'Em entrega':['Entregue']};return transitions[order.status]?.includes(next)===true}

function sellerOrdersPanel(os){if(commercial)return commercialSellerOrders(os);
 const options=[['all','Todos'],['Recebido','Novos'],['Em preparo','Em preparação'],['Pronto para retirada','Prontos'],['Em entrega','Em entrega'],['Entregue','Concluídos'],['Cancelado','Cancelados'],['Recusado','Recusados']];
 const shown=os.filter(o=>sellerOrderFilter==='all'||o.status===sellerOrderFilter);
 const filters=options.map(([value,label])=>`<button class="pill ${sellerOrderFilter===value?'active':''}" data-order-filter="${value}">${label}</button>`).join('');
 const cards=shown.map(o=>{const details=o.addressDetails||{},items=(o.items||[]).map(i=>`<li>${Number(i.qty)||0}× ${esc(i.name)}${i.note?` <small>(${esc(i.note)})</small>`:''}${i.extras?.length?` <small>Adicionais: ${i.extras.map(x=>esc(x.name)).join(', ')}</small>`:''}</li>`).join(''),actions=o.status==='Recebido'?`<button class="btn outline" data-status="${o.id}" data-next="Recusado">Recusar</button><button class="btn" data-status="${o.id}" data-next="Em preparo">Aceitar pedido</button>`:o.status==='Em preparo'?`<button class="btn" data-status="${o.id}" data-next="Pronto para retirada">Marcar pronto</button>`:o.status==='Pronto para retirada'?`<button class="btn" data-status="${o.id}" data-next="${o.fulfillment==='pickup'?'Entregue':'Em entrega'}">${o.fulfillment==='pickup'?'Concluir retirada':'Saiu para entrega'}</button>`:o.status==='Em entrega'?`<button class="btn" data-status="${o.id}" data-next="Entregue">Concluir entrega</button>`:'';return `<article class="seller-order-card"><header><div><strong>Pedido #${o.id.slice(-5)}</strong><span>${new Date(o.created).toLocaleString('pt-BR',{dateStyle:'short',timeStyle:'short'})}</span></div><span class="status">${esc(o.status)}</span></header><div class="seller-order-grid"><section><b>Cliente</b><span>${esc(o.customer)}</span><b>Produtos</b><ul>${items||'<li>Itens não disponíveis</li>'}</ul>${o.notes?`<b>Observações</b><span>${esc(o.notes)}</span>`:''}</section><section><b>Entrega</b><span>${esc(o.address||'Endereço não informado')}${details.number&&o.address&&!o.address.includes(details.number)?', '+esc(details.number):''}</span>${details.complement?`<span>${esc(details.complement)}</span>`:''}${o.reference||details.reference?`<b>Ponto de referência</b><span>${esc(o.reference||details.reference)}</span>`:''}<b>Pagamento</b><span>${esc(o.payment||'Não informado')}${sPaymentKey(o.payment,o.store)}</span>${o.addressCoordinates?`<a class="text-btn" target="_blank" rel="noopener" href="https://www.openstreetmap.org/?mlat=${o.addressCoordinates.lat}&mlon=${o.addressCoordinates.lng}#map=18/${o.addressCoordinates.lat}/${o.addressCoordinates.lng}">Abrir ponto no mapa</a>`:''}</section></div><footer><div><span>Produtos ${money(o.subtotal||0)}</span><span>Entrega ${money(o.delivery||0)}</span><strong>Total ${money(o.total||0)}</strong></div><div class="seller-actions"><button class="btn outline" data-order-detail="${esc(o.id)}">Ver detalhes</button><button class="btn outline" data-print="${o.id}">Imprimir</button>${actions}</div></footer></article>`}).join('');
 return `<div class="filters seller-order-filters">${filters}</div><div class="seller-orders">${cards||'<div class="empty">Nenhum pedido neste filtro.</div>'}</div>`;
}
function sPaymentKey(payment,storeId){if(!String(payment||'').toLowerCase().includes('pix'))return '';const key=data.stores.find(store=>store.id===storeId)?.pixKey;return key?` · ${esc(key)}`:''}

function sellerSalesPanel(os){if(commercial)return commercialController.financePage(data.current.storeId)+commercialSales(os);
 const now=new Date(),start=new Date(now.getFullYear(),now.getMonth(),now.getDate());
 if(salesPeriod==='week'){const day=(start.getDay()+6)%7;start.setDate(start.getDate()-day)}
 if(salesPeriod==='month')start.setDate(1);
 const period=os.filter(o=>Number(o.created)>=start.getTime()&&Number(o.created)<=Date.now()),valid=period.filter(o=>!['Cancelado','Recusado'].includes(o.status)),done=period.filter(o=>o.status==='Entregue'),cancelled=period.filter(o=>['Cancelado','Recusado'].includes(o.status)),gross=valid.reduce((sum,o)=>sum+(Number(o.subtotal)||0),0),delivery=valid.reduce((sum,o)=>sum+(Number(o.delivery)||0),0),items=valid.flatMap(o=>o.items||[]),sold=items.reduce((sum,i)=>sum+(Number(i.qty)||0),0),ranking={};
 items.forEach(item=>ranking[item.name]=(ranking[item.name]||0)+(Number(item.qty)||0));const top=Object.entries(ranking).sort((a,b)=>b[1]-a[1])[0],rate=commissionRate(),labels={today:'Hoje',week:'Esta semana',month:'Este mês'};
 return `<div class="filters seller-order-filters">${Object.entries(labels).map(([value,label])=>`<button class="pill ${salesPeriod===value?'active':''}" data-sales-period="${value}">${label}</button>`).join('')}</div><div class="dash-card"><div class="dash-card-head"><strong>Relatório de vendas · ${labels[salesPeriod]}</strong></div><div class="dash-card-body"><div class="seller-report-grid"><div><small>Faturamento bruto (produtos)</small><strong>${money(gross)}</strong></div><div><small>Taxas de entrega</small><strong>${money(delivery)}</strong></div><div><small>Pedidos</small><strong>${period.length}</strong></div><div><small>Concluídos</small><strong>${done.length}</strong></div><div><small>Cancelados/recusados</small><strong>${cancelled.length}</strong></div><div><small>Ticket médio</small><strong>${money(valid.length?gross/valid.length:0)}</strong></div><div><small>Itens vendidos</small><strong>${sold}</strong></div><div><small>Mais vendido</small><strong>${top?esc(top[0])+' ('+top[1]+')':'—'}</strong></div></div><table class="table"><tbody><tr><th>Resumo da comissão</th><th>Valor</th></tr><tr><td>Comissão NortFood (${(rate*100).toLocaleString('pt-BR')}%)</td><td>${money(gross*rate)}</td></tr><tr><td>Repasse estimado ao estabelecimento</td><td>${money(gross*(1-rate))}</td></tr></tbody></table><p>Estimativa local sobre os produtos vendidos. A cobrança e o repasse reais dependem de backend e provedor de pagamento.</p></div></div><div class="dash-card"><div class="dash-card-head"><strong>Pedidos deste período</strong></div><div class="dash-card-body">${period.map(o=>`<div class="order-row"><span>${new Date(o.created).toLocaleString('pt-BR')} · #${o.id.slice(-5)} · ${esc(o.status)}</span><b>${money(o.subtotal||0)}</b></div>`).join('')||'<div class="empty">Sem pedidos neste período.</div>'}</div></div>`
}
function seller(){
 const s=data.stores.find(store=>store.id===data.current?.storeId);
 if(data.current?.role!=='seller'||!s){view='home';return '<main class="wrap"><div class="empty">Não foi possível abrir o painel deste estabelecimento.</div></main>'}
 const orders=data.orders.filter(order=>order.store===s.id).sort((a,b)=>b.created-a.created),today=new Date().toDateString(),todayOrders=orders.filter(order=>new Date(order.created).toDateString()===today),todaySales=todayOrders.filter(order=>!['Cancelado','Recusado'].includes(order.status)).reduce((sum,order)=>sum+(Number(order.subtotal)||0),0),rate=commissionRate(),newOrders=orders.filter(order=>order.status==='Recebido').length,preparing=orders.filter(order=>order.status==='Em preparo').length,inDelivery=orders.filter(order=>order.status==='Em entrega').length,unavailable=s.products.filter(product=>product[6]===false).length,unread=(data.conversations||[]).filter(conversation=>conversation.storeId===s.id).reduce((sum,conversation)=>sum+(conversation.messages||[]).filter(message=>message.unreadFor==='seller').length,0);
 let body='';
 if(tab==='orders')body=sellerOrdersPanel(orders);
 if(tab==='products')body=`<div class="dash-card"><div class="dash-card-head"><strong>Cardápio · ${esc(s.name)}</strong><button class="btn small" data-action="add-product">+ Produto</button></div><div class="dash-card-body">${s.products.length?s.products.map((product,index)=>`<article class="product-admin"><span class="admin-product-info">${product[5]?`<img src="${imageAttr(product[5])}" alt="">`:''}<span><b>${esc(product[0])}</b><div class="section-sub">${esc(product[1])} · ${esc(productCategory(product))} · ${product[6]===false?'Indisponível':'Disponível'}</div>${product[7]?.length?`<small>Adicionais: ${product[7].map(extra=>esc(extra.name)+' '+money(extra.price)).join(', ')}</small>`:''}${product[8]?`<small>Observações: ${esc(product[8])}</small>`:''}</span></span><span class="admin-product-actions"><b>${money(product[2])}</b><button class="btn outline small" data-product-move="${index}" data-step="-1" aria-label="Mover produto para cima" ${index===0?'disabled':''}>↑</button><button class="btn outline small" data-product-move="${index}" data-step="1" aria-label="Mover produto para baixo" ${index===s.products.length-1?'disabled':''}>↓</button><button class="btn outline small" data-product-edit="${index}">Editar</button><button class="btn outline small" data-product-toggle="${index}">${product[6]===false?'Ativar':'Desativar'}</button><button class="text-btn" data-product-delete="${index}">Excluir</button></span></article>`).join(''):'<div class="empty">Seu cardápio ainda está vazio.<br><button class="btn" data-action="add-product">Adicionar primeiro produto</button></div>'}</div></div><div class="dash-card"><div class="dash-card-head"><strong>Prévia para clientes</strong><button class="btn outline small" data-open="${s.id}">Visualizar cardápio</button></div></div>`;
 if(tab==='sales')body=sellerSalesPanel(orders);
 if(tab==='settings')body=storeSettingsForm(s);
 const status=storeStatus(s);
 return `<main class="wrap"><div class="dashboard-top"><div><span class="eyebrow">PAINEL DO ESTABELECIMENTO</span><h1>Olá, ${esc(s.name)} 👋</h1><p>${commercial?'Pedidos e atualizações são confirmados pelo servidor.':'Pedidos e dados ficam salvos neste navegador nesta versão demonstrativa.'}</p></div><div class="seller-top-actions"><span class="open-status">${status.label}</span><button class="btn ${status.open?'outline':''}" data-action="toggle-store">${status.open?'Fechar loja':'Abrir loja'}</button><button class="btn outline small" data-view="home">Ver marketplace ↗</button></div></div><div class="stat-grid"><div class="stat"><label>Vendas de hoje</label><strong>${money(todaySales)}</strong><em>${todayOrders.length} pedidos</em></div><div class="stat"><label>Pedidos novos</label><strong>${newOrders}</strong><em>Precisam de resposta</em></div><div class="stat"><label>Em preparação</label><strong>${preparing}</strong><em>Pedidos em andamento</em></div><div class="stat"><label>Em entrega</label><strong>${inDelivery}</strong><em>Entrega do estabelecimento</em></div><div class="stat"><label>Comissão estimada · ${(rate*100).toLocaleString('pt-BR')}%</label><strong>${money(todaySales*rate)}</strong><em>Demonstrativo</em></div><div class="stat"><label>Mensagens não lidas</label><strong>${unread}</strong><em><button class="text-btn" data-view="conversations">Ver conversas</button></em></div></div>${unavailable?`<p class="seller-stock-alert">${unavailable} produto(s) indisponível(is) no cardápio. <button class="text-btn" data-tab="products">Revisar cardápio</button></p>`:''}<nav class="seller-shortcuts" aria-label="Áreas do estabelecimento"><button class="pill ${tab==='orders'?'active':''}" data-tab="orders">Pedidos${newOrders?` · ${newOrders}`:''}</button><button class="pill ${tab==='products'?'active':''}" data-tab="products">Cardápio</button><button class="pill ${tab==='settings'?'active':''}" data-tab="settings">Perfil da loja</button><button class="pill ${tab==='sales'?'active':''}" data-tab="sales">Vendas</button><button class="pill" data-view="conversations">Chat${unread?` · ${unread}`:''}</button><button class="pill" data-view="notifications">Notificações</button><button class="pill" data-view="settings">Configurações</button></nav>${body}<p class="section-sub">${esc(s.deliveryInfo||'Entrega feita pelo estabelecimento')} · A comissão exibida é estimativa e usa as configurações da plataforma.</p></main>${footer()}`
}

function saveStoreProfile(f,d){
 if(data.current?.role!=='seller')return toast('Acesso exclusivo para estabelecimentos.');
 const s=data.stores.find(x=>x.id===data.current.storeId),categories=[...new Set(d.getAll('categories').map(x=>String(x).trim()).filter(Boolean))],days=d.getAll('workingDays').map(Number),payments=d.getAll('payments').map(String);
 if(!s)return toast('Estabelecimento não encontrado.');if(!categories.length)return toast('Selecione ao menos uma categoria.');if(!days.length)return toast('Selecione ao menos um dia de funcionamento.');if(!payments.length)return toast('Selecione ao menos uma forma de pagamento.');
 const hours=String(d.get('hours')||''),deliveryFee=Number(d.get('deliveryFee')),minimumOrder=Number(d.get('minimumOrder')||0);
 if(!/^(?:[01]\d|2[0-3]):[0-5]\d-(?:[01]\d|2[0-3]):[0-5]\d$/.test(hours))return toast('Use o horário no formato 11:00-22:00.');if(!Number.isFinite(deliveryFee)||deliveryFee<0||!Number.isFinite(minimumOrder)||minimumOrder<0)return toast('Confira taxa de entrega e valor mínimo.');
 const files=[...f.querySelectorAll('input[type=file]')].filter(input=>input.files[0]);if(files.some(input=>input.files[0].size>1024*1024))return toast('Cada imagem deve ter até 1 MB.');
 Promise.all(files.map(input=>new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve([input.name,reader.result]);reader.onerror=()=>reject(new Error('image-read'));reader.readAsDataURL(input.files[0])}))).then(images=>{
  const previous={...s};s.name=String(d.get('name')||'').trim();s.about=String(d.get('about')||'').trim();s.categories=categories;s.category=categories[0];s.phone=String(d.get('phone')||'').trim();s.whatsapp=String(d.get('whatsapp')||'').trim();s.street=String(d.get('street')||'').trim();s.number=String(d.get('number')||'').trim();s.complement=String(d.get('complement')||'').trim();s.neighborhood=String(d.get('neighborhood')||'').trim();s.city=String(d.get('city')||'').trim();s.address=[s.street,s.number,s.complement,s.neighborhood,s.city].filter(Boolean).join(', ');s.hours=hours;s.workingDays=days;s.pickupEnabled=!!f.querySelector('[name=pickupEnabled]')?.checked;s.deliveryFee=deliveryFee;s.minimumOrder=minimumOrder;s.time=String(d.get('time')||'').trim();s.acceptedPayments=payments;s.pixKey=String(d.get('pixKey')||'').trim();s.deliveryInfo=String(d.get('deliveryInfo')||'').trim();s.fee=deliveryFee===0?'Grátis':money(deliveryFee);
  Object.assign(s,window.NortFoodLocation.readPatch(f));
  for(const [name,url] of images)if(url)s[name==='logo'?'logo':'cover']=url;
  try{save()}catch{Object.assign(s,previous);return toast('Não foi possível salvar. O armazenamento deste navegador pode estar cheio.')}
  render();toast('Perfil do estabelecimento atualizado.');
 }).catch(()=>toast('Não foi possível carregar a imagem. Tente novamente.'))
}

function openProductForm(index=-1){if(data.current?.role!=='seller')return toast('Acesso exclusivo para estabelecimentos.');let s=data.stores.find(x=>x.id===data.current.storeId);if(!s)return toast('Loja não encontrada.');let p=index>=0?s.products[index]:null,extras=(p?.[7]||[]).map(extra=>extra.name+':'+Number(extra.price||0)).join('\n');modal(`<div class="modal-head"><div><h2>${p?'Editar produto':'Novo produto'}</h2><p>Organize os itens do seu cardápio.</p></div><button class="close" data-action="close-modal">×</button></div><form id="product-form" class="form" data-index="${index}"><div class="field"><label>NOME</label><input name="name" required maxlength="80" value="${esc(p?.[0]||'')}"></div><div class="field"><label>DESCRIÇÃO</label><textarea name="desc" required maxlength="300">${esc(p?.[1]||'')}</textarea></div><div class="field"><label>PREÇO</label><input name="price" type="number" min=".01" step=".01" required value="${p?Number(p[2]):''}"></div><div class="field"><label>CATEGORIA DO PRODUTO</label><input name="category" required maxlength="40" list="product-categories" value="${esc(p?productCategory(p):'')}"><datalist id="product-categories"><option>Hambúrgueres</option><option>Bebidas</option><option>Sobremesas</option><option>Pratos</option><option>Pizzas</option></datalist></div><div class="field"><label>ÍCONE</label><select name="emoji">${['🍽️','🍔','🍕','🍰','🥤','🍲','🍦'].map(x=>`<option ${p?.[3]===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="field"><label>IMAGEM DO PRODUTO</label><input type="file" name="image" accept="image/*">${p?.[5]?'<small>Envie outra imagem para substituir a atual.</small>':''}</div><div class="field"><label>ADICIONAIS (um por linha: nome:preço)</label><textarea name="extras" placeholder="Queijo:3,50\nBacon:4,00">${esc(extras)}</textarea><small>Use preço 0 para adicional sem custo.</small></div><div class="field"><label>OBSERVAÇÕES PARA ESTE PRODUTO</label><input name="productNotes" maxlength="180" value="${esc(p?.[8]||'')}" placeholder="Ex.: ponto da carne, escolha de sabor"></div><label><input type="checkbox" name="available" ${p?.[6]===false?'':'checked'}> Disponível para pedidos</label>${commercial?'<div class="field"><label>Grupo de opções</label><input name="groupName" value="'+esc(p?.[10]?.[0]?.name||'Adicionais')+'"></div><div class="form-two-columns"><label>Mínimo de escolhas<input name="minChoices" type="number" min="0" max="20" value="'+(p?.[10]?.[0]?.min_choices||0)+'"></label><label>Máximo de escolhas<input name="maxChoices" type="number" min="1" max="20" value="'+(p?.[10]?.[0]?.max_choices||p?.[7]?.length||1)+'"></label></div>':''}<button class="btn">${p?'Salvar alterações':'Adicionar produto'}</button><button type="button" class="btn outline" data-action="close-modal">Cancelar</button></form>`)}
function addProductToCart(store,index,extras=[],note='',quantity=1){if(commercial){try{window.NortFoodQR?.validate(data.stores.find(s=>s.id===store))}catch(error){toast(error.message);return false}}if(data.current?.role==='seller')return toast('Use uma conta de cliente para pedir.');const s=data.stores.find(item=>item.id===store),p=s?.products[index];if(!p||p[6]===false)return toast('Este produto está indisponível.');if(!storeStatus(s).open)return toast('Este estabelecimento está fechado.');if(data.cart.some(row=>products().find(p=>p.id===row.pid)?.store!==store)){pendingProduct={store,index,extras,note,quantity};modal('<div class="modal-head"><h2>Trocar de estabelecimento?</h2><button class="close" data-action="close-modal">×</button></div><p>Seu carrinho contém itens de outra loja. Ao continuar, esses itens serão substituídos. Cada pedido pertence a um estabelecimento.</p><button class="btn outline" data-action="close-modal">Manter carrinho</button><button class="btn" data-replace-cart>Substituir carrinho</button>');return false}const pid=p[9]||(p[9]||store+'-'+index),key=JSON.stringify(extras.map(extra=>extra.name).sort())+'|'+note,existing=data.cart.find(row=>row.pid===pid&&row.variantKey===key);if(!Number.isInteger(quantity)||quantity<1||quantity>20)return toast('Escolha de 1 a 20 unidades.');if(existing)existing.qty+=quantity;else data.cart.push({pid,qty:quantity,extras,note,variantKey:key});save();let count=document.querySelector('.cart-count');if(count)count.textContent=data.cart.reduce((n,row)=>n+row.qty,0);toast('Item adicionado ao carrinho.');window.NortFoodSite?.track('add_to_cart',pid+':'+data.cart.reduce((n,x)=>n+x.qty,0));return true}
function openProductOptions(store,index){productDetail(store,index)}
function notificationVisible(n){if(!data.current)return false;if(n.audience==='seller')return data.current.role==='seller'&&n.storeId===data.current.storeId;if(n.audience==='customer')return data.current.role==='customer'&&n.email===data.current.email;if(data.current.role==='seller')return n.storeId===data.current.storeId;return n.email===data.current.email}
function visibleNotifications(){return(data.notifications||[]).filter(notificationVisible)}

function becomeSeller(){if(commercial&&data.current?.role==='customer'){view='profile';render();document.querySelector('#store-request-form input')?.focus();return}if(data.current?.role==='seller'){view='seller';tab='orders';render();return}authMode='register';authRole='seller';authForm()}
function checkout(){if(['seller','admin'].includes(data.current?.role))return toast('Entre com uma conta de cliente para pedir.');if(!data.cart.length)return toast('Seu carrinho está vazio.');if(!data.current){closeCart();auth();return toast('Entre para concluir o pedido.')}let its=data.cart.map(r=>({...products().find(p=>p.id===r.pid),qty:r.qty})).filter(x=>x.id);if(!its.length){data.cart=[];save();drawCart();return toast('Os itens do carrinho não estão mais disponíveis.')}let s=data.stores.find(x=>x.id===its[0].store);if(!s)return toast('A loja deste pedido não está disponível.');if(!storeStatus(s).open)return toast('Este estabelecimento está fechado e não pode receber pedidos agora.');if(its.some(x=>x.store!==s.id))return toast('Faça um pedido por estabelecimento.');if(cartSubtotal()<(Number(s.minimumOrder)||0))return toast('O pedido mínimo desta loja é '+money(s.minimumOrder)+'.');closeCart();if(commercial){try{window.NortFoodQR?.validate(s)}catch(error){return toast(error.message)}if(window.NortFoodQR?.mode(s)){fulfillment='dine_in';showCheckoutPayment();return}}fulfillment='delivery';addressCheckout=true;addressOriginView=view;if(s.pickupEnabled&&s.address){modal('<div class="modal-head"><h2>Como deseja receber?</h2><button class="close" data-action="close-modal">×</button></div><button class="btn" data-fulfillment="delivery" '+(commercial&&s.deliveryEnabled===false?'disabled':'')+'>Entrega pela loja · '+deliveryFeeLabel(s)+'</button><button class="btn outline" data-fulfillment="pickup">Retirada no estabelecimento · grátis</button>')}else{view='addresses';render()}}

function printOrder(id){let o=accessibleOrder(id);if(!o)return;let w=window.open('','_blank','width=420,height=700');if(!w)return toast('Permita pop-ups para imprimir.');const mapLink=o.addressCoordinates?`<br>Localização: https://www.openstreetmap.org/?mlat=${o.addressCoordinates.lat}&mlon=${o.addressCoordinates.lng}#map=18/${o.addressCoordinates.lat}/${o.addressCoordinates.lng}`:'';w.document.write(`<!doctype html><title>Pedido ${o.id}</title><style>body{font:14px Arial;padding:25px;max-width:360px;margin:auto}hr{border:0;border-top:1px dashed #777}li{padding:6px 0}a{overflow-wrap:anywhere}</style><h1>NortFood · #${o.id.slice(-5)}</h1><p>${commercial?'Comanda sem valor fiscal. Pedido registrado no servidor.':'Comprovante demonstrativo, sem valor fiscal. Pedido local; pagamento não processado.'}</p><p>${new Date(o.created).toLocaleString('pt-BR')}</p><hr><h3>${esc(o.storeName)}</h3><p>Cliente: ${esc(o.customer)}${o.customerPhone?'<br>Telefone: '+esc(o.customerPhone):''}<br>Entrega: ${esc(o.address)}${o.reference?'<br>Referência: '+esc(o.reference):''}<br>Pagamento: ${esc(o.payment)}${mapLink}</p><hr><ul>${o.items.map(i=>`<li>${i.qty}× ${esc(i.name)} — ${money(i.price*i.qty)}${i.extras?.length?'<br>'+i.extras.map(x=>esc(x.name)).join(', '):''}${i.note?'<br>'+esc(i.note):''}</li>`).join('')}</ul><hr><p>Produtos: ${money(o.subtotal)}<br>Entrega: ${money(o.delivery)}<br><b>Total: ${money(o.total)}</b></p><p>Observação: ${esc(o.notes||'—')}</p><script>onload=()=>print()<\/script>`);w.document.close()}

