function localNotice(){if(commercial)return '<p class="demo-notice">Pedidos são confirmados pelo servidor. Pagamento e entrega são responsabilidade da loja. Não há aprovação bancária automática.</p>';return '<p class="demo-notice">Demonstração local: pedidos, mensagens e avaliações ficam neste navegador. Nenhum pagamento é processado.</p>'}
function pageHeading(title,description,back='profile'){return '<div class="view-title"><div><button class="back" data-view="'+back+'">← Voltar</button><h1>'+esc(title)+'</h1><p>'+esc(description)+'</p></div></div>'}
function filterControls(){return '<div class="filters discovery-filters"><label>Ordenar <select data-discovery-sort><option value="featured" '+(sortMode==='featured'?'selected':'')+'>Destaques</option><option value="rating" '+(sortMode==='rating'?'selected':'')+'>'+(commercial?'Melhor avaliação':'Avaliação demonstrativa')+'</option><option value="time" '+(sortMode==='time'?'selected':'')+'>Menor tempo</option></select></label><label><input type="checkbox" data-only-open '+(onlyOpen?'checked':'')+'> Abertos agora</label><label>Categoria <select data-discovery-category>'+publicCategories().map(category=>'<option value="'+category.id+'" '+(filter===category.label?'selected':'')+'>'+esc(category.label)+'</option>').join('')+'</select></label></div>'}
function matchingStores(){const needle=query.trim().toLocaleLowerCase('pt-BR');return data.stores.filter(s=>(!commercial||s.status==='approved')&&(filter==='Todos'||storeCategories(s).includes(filter))&&(!onlyOpen||storeStatus(s).open)&&(!needle||[s.name,...storeCategories(s),...s.products.map(p=>p[0]+' '+p[1])].join(' ').toLocaleLowerCase('pt-BR').includes(needle))).sort((a,b)=>sortMode==='rating'?b.rating-a.rating:sortMode==='time'?parseInt(a.time)-parseInt(b.time):Number(b.featured)-Number(a.featured))}
