function recentData(){const key=data.current?.email||'guest';data.preferences[key]||={};return data.preferences[key]}
function rememberSearch(){const term=query.trim();if(!term)return;const p=recentData();p.searches=[term,...(p.searches||[]).filter(x=>x!==term)].slice(0,6);save()}
