function recentDiscovery(){if(query.trim())return '';const p=recentData();return '<section class="recent-discovery">'+(p.searches?.length?'<h2>Buscas recentes</h2><div class="detail-actions">'+p.searches.map(term=>'<button class="pill" data-recent-search="'+esc(term)+'">'+esc(term)+'</button>').join('')+'</div>':'')+(p.recentStores?.length?'<h2>Vistos recentemente</h2><div class="store-grid">'+p.recentStores.map(id=>data.stores.find(s=>s.id===id)).filter(Boolean).map(card).join('')+'</div>':'')+'</section>'}

function discoveryPage(){const stores=matchingStores(),ids=new Set(stores.map(s=>s.id)),needle=query.trim().toLocaleLowerCase('pt-BR'),items=products().filter(p=>ids.has(p.store)&&(!needle||(p.name+' '+p.desc).toLocaleLowerCase('pt-BR').includes(needle)));return '<main class="wrap">'+pageHeading('Buscar sabores locais','Encontre lojas e produtos em Porteirinha.','home')+'<div class="switch"><button data-search-kind="stores" class="'+(searchKind==='stores'?'active':'')+'">Estabelecimentos · '+stores.length+'</button><button data-search-kind="products" class="'+(searchKind==='products'?'active':'')+'">Produtos · '+items.length+'</button></div>'+recentDiscovery()+filterControls()+'<div class="'+(searchKind==='stores'?'store-grid':'discovery-grid')+'">'+((searchKind==='stores'?stores.map(card):items.map(productTile)).join('')||'<div class="empty">Nenhum resultado. Tente outra busca ou categoria.<br><button class="btn soft" data-clear>Limpar filtros</button></div>')+'</div></main>'+footer()}
