function productDetail(store,index){const s=data.stores.find(x=>x.id===store),p=s?.products[index];if(!p)return toast('Produto não encontrado.');modal('<div class="modal-head"><h2>'+esc(p[0])+'</h2><button class="close" data-action="close-modal" aria-label="Fechar detalhes">×</button></div>'+(p[5]?'<img class="detail-product-image" src="'+imageAttr(p[5])+'" alt="'+esc(p[0])+'">':'<div class="detail-product-placeholder" aria-hidden="true">'+esc(p[3]||'•')+'</div>')+'<p>'+esc(p[1])+'</p><p>'+esc(s.name)+' · '+money(p[2])+'</p><button class="text-btn" data-product-fav="'+esc((p[9]||store+'-'+index))+'">'+(favoriteList('products').includes((p[9]||store+'-'+index))?'Remover dos favoritos':'Salvar nos favoritos')+'</button><form class="form" id="product-options" data-store="'+esc(store)+'" data-index="'+index+'">'+(p[7]?.length?'<fieldset class="field"><legend>Adicionais</legend>'+p[7].map((x,i)=>'<label class="extra-choice"><input type="checkbox" name="extra" value="'+i+'" data-option-price="'+Number(x.price||0)+'"> '+esc(x.name)+' + '+money(x.price||0)+'</label>').join('')+'</fieldset>':'')+'<div class="field"><label for="product-note">'+esc(p[8]||'Observações (opcional)')+'</label><input id="product-note" name="note" maxlength="180" placeholder="Alguma preferência?"></div><div class="field"><label for="product-quantity">Quantidade</label><input id="product-quantity" name="quantity" type="number" min="1" max="20" value="1" required data-base-price="'+Number(p[2])+'"></div><button class="btn" data-product-total '+(!storeStatus(s).open||p[6]===false||data.current?.role==='seller'?'disabled':'')+'>Adicionar · '+money(p[2])+'</button>'+(!storeStatus(s).open||p[6]===false?'<p>Este produto ou estabelecimento está indisponível.</p>':'')+'</form>')}
