function orderDetailPage(){const o=accessibleOrder(selectedOrder);if(!o)return '<main class="wrap">'+pageHeading('Pedido indisponível','Entre na conta responsável por este pedido.','orders')+'</main>';const steps=commercial?(o.fulfillment==='dine_in'?['Recebido','Aceito','Em preparo','Pronto para servir','Servido']:o.fulfillment==='pickup'?['Recebido','Aceito','Em preparo','Pronto para retirada','Retirado']:['Recebido','Aceito','Em preparo','Pronto para entrega','Em entrega','Entregue']):o.fulfillment==='pickup'?['Recebido','Em preparo','Pronto para retirada','Entregue']:['Recebido','Em preparo','Pronto para retirada','Em entrega','Entregue'],at=steps.indexOf(o.status),ended=['Cancelado','Recusado'].includes(o.status);return '<main class="wrap order-detail">'+pageHeading('Pedido #'+o.id.slice(-5),o.storeName,data.current.role==='seller'?'seller':'orders')+localNotice()+'<section class="dash-card"><div class="dash-card-body"><h2>'+esc(o.status)+'</h2>'+(o.fulfillment==='dine_in'?'<p class="table-context">Pedido presencial — '+esc(o.tableLabel)+'</p>':o.fulfillment==='pickup'?pickupLocation(o):'')+'<ol class="order-timeline">'+steps.map((label,i)=>{const event=(o.timeline||[]).find(x=>x.status===label);return '<li class="'+(!ended&&i<=at?'reached':'')+'"><strong>'+label+'</strong><small>'+(event?new Date(event.created).toLocaleString('pt-BR'):i===0?new Date(o.created).toLocaleString('pt-BR'):o.timeline?.length?'Aguardando atualização':'Horário não registrado')+'</small></li>'}).join('')+'</ol>'+(ended?'<p>'+esc(o.status)+': este pedido foi encerrado.</p>':'')+'<p>'+ (o.fulfillment==='dine_in'?'Pedido presencial · '+esc(o.tableLabel)+'. Aguarde o atendimento da equipe.':o.fulfillment==='pickup'?'Retire no estabelecimento quando o pedido estiver pronto.':'A loja é responsável pela entrega. Não há rastreamento GPS nesta versão.')+'</p><button class="btn soft" data-chat-store="'+esc(o.store)+'">Conversar com a loja</button></div></section><section class="dash-card"><div class="dash-card-body"><h2>'+(commercial?'Resumo e comanda':'Resumo e comprovante demonstrativo')+'</h2><p>'+new Date(o.created).toLocaleString('pt-BR')+'</p><p>'+esc(o.customer)+' · '+esc(o.payment)+'</p><p>'+esc(o.address)+'</p>'+(o.reference?'<p>Referência: '+esc(o.reference)+'</p>':'')+orderItems(o.items)+'<div class="total-line"><span>Produtos</span><strong>'+money(o.subtotal)+'</strong></div><div class="total-line"><span>'+(o.fulfillment==='dine_in'?'Atendimento na mesa':o.fulfillment==='pickup'?'Retirada':'Entrega')+'</span><strong>'+money(o.delivery)+'</strong></div><div class="total-line final"><span>Total</span><strong>'+money(o.total)+'</strong></div><p>Observações: '+esc(o.notes||'Nenhuma')+'</p><small>'+(commercial?'Comanda sem valor fiscal. Pagamento recebido diretamente pela loja.':'Registro local sem valor fiscal. Pagamento não processado pela plataforma.')+'</small><div class="detail-actions"><button class="btn outline" data-print="'+esc(o.id)+'">Imprimir comprovante</button>'+(data.current.role==='customer'&&o.status==='Recebido'?'<button class="btn outline" data-cancel="'+esc(o.id)+'">'+(commercial?'Cancelar pedido':'Cancelar pedido local')+'</button>':'')+(data.current.role==='customer'&&['Entregue','Retirado','Servido'].includes(o.status)?'<button class="btn" data-review-order="'+esc(o.id)+'">'+(data.reviews.some(r=>r.order===o.id)?'Editar avaliação':'Avaliar loja')+'</button>':'')+'</div></div></section></main>'+footer()}
function orderItems(items){return '<ul class="review-items">'+items.map(x=>'<li><div><strong>'+Number(x.qty)+'× '+esc(x.name)+'</strong>'+(x.extras?.length?'<small>'+x.extras.map(e=>esc(e.name)).join(', ')+'</small>':'')+(x.note?'<small>'+esc(x.note)+'</small>':'')+'</div><b>'+money(x.price*x.qty)+'</b></li>').join('')+'</ul>'}
