function addresses(){const u=data.current;if(commercial)return u?.savedAddresses||[];if(!u||u.role!=='customer')return [];u.savedAddresses||=[];if(!u.savedAddresses.length&&u.address){u.savedAddresses.push({id:'legacy',label:'Principal',street:u.addressDetails?.street||u.address,number:u.addressDetails?.number||'',complement:u.addressDetails?.complement||'',reference:u.addressDetails?.reference||'',formatted:u.address,coordinates:u.addressCoordinates||null})}return u.savedAddresses}
function addressBookPage(){if(data.current?.role!=='customer')return '<main class="wrap"><div class="empty">Endereços disponíveis para clientes.</div></main>';return '<main class="wrap">'+pageHeading('Meus endereços',addressCheckout?'Selecione o destino deste pedido.':'Endereços salvos apenas nesta conta.',addressCheckout?'home':'profile')+'<div class="address-list">'+(addresses().map(a=>'<article class="dash-card"><div class="dash-card-body"><strong>'+esc(a.label)+'</strong><p>'+esc(a.formatted)+'</p><p>'+esc(a.reference||'')+'</p><div class="detail-actions"><button class="btn '+(a.formatted===data.current.address?'soft':'outline')+'" data-select-address="'+esc(a.id)+'">'+(addressCheckout?'Entregar aqui':a.formatted===data.current.address?'Endereço principal':'Usar como principal')+'</button><button class="text-btn" data-edit-address="'+esc(a.id)+'">Editar</button></div></div></article>').join('')||'<div class="empty">Cadastre seu primeiro endereço.</div>')+'</div><div class="detail-actions"><button class="btn" data-new-address>Adicionar endereço manual</button><button class="btn outline" data-address-map>Escolher no mapa</button></div></main>'+footer()}
function manualAddress(id=''){if(data.current?.role!=='customer')return auth();editingAddress=id;const a=addresses().find(x=>x.id===id)||{};modal('<div class="modal-head"><h2>'+ (id?'Editar endereço':'Novo endereço')+'</h2><button class="close" data-action="close-modal">×</button></div><form id="manual-address-form" class="form">'+[['label','Nome do endereço',a.label||'Casa',40],['street','Rua / avenida',a.street||'',180],['number','Número (ou s/n)',a.number||'',30],['complement','Complemento (opcional)',a.complement||'',100],['reference','Referência (opcional)',a.reference||'',120]].map(([name,label,value,max])=>'<div class="field"><label for="address-'+name+'">'+label+'</label><input id="address-'+name+'" name="'+name+'" maxlength="'+max+'" value="'+esc(value)+'" '+(['label','street','number'].includes(name)?'required':'')+'></div>').join('')+'<p class="section-sub">Porteirinha, MG. Confirme a cobertura de entrega com a loja.</p><button class="btn">Salvar endereço</button></form>')}
function applyAddress(a){data.current.address=a.formatted;data.current.addressDetails={...a};if(a.coordinates)data.current.addressCoordinates={...a.coordinates};else delete data.current.addressCoordinates}
function helpPage(){const faq=commercial? [['Como faço um pedido?','Escolha uma loja aprovada e aberta, selecione produtos e adicionais, informe um endereço em bairro atendido ou retirada e revise os valores. O servidor confirma o registro.'],['Quando posso usar o marketplace?','O Supabase precisa estar configurado e o piloto autorizado pelo administrador após testes, contrato e revisão de privacidade. Sem isso, novos pedidos ficam bloqueados.'],['Quem faz a entrega?','Cada estabelecimento prepara e entrega os próprios pedidos. O NortFood não possui frota.'],['Como acompanho meu pedido?','Em Pedidos, abra os detalhes. As mudanças vêm do servidor. Mantenha o painel aberto; não há push com o navegador fechado.'],['Como pago?','O pagamento é realizado diretamente à loja ao receber, pelo método selecionado. Registrar pedido não significa aprovação bancária.'],['O que faço quando a conexão cai?','Não repita o pedido com outra tentativa. Confira o histórico e retome a confirmação; a chave da tentativa protege contra duplicação.'],['Como falo com a loja?','Abra Conversas ou o perfil da loja. Mensagens só são confirmadas após serem registradas no servidor.'],['Como salvo meu endereço?','Use Endereços no Perfil. O formulário manual funciona sem GPS/mapa; bairro é obrigatório para validar a cobertura.'],['Como recupero minha senha?','Use Recuperar acesso na tela de login. A confirmação depende de e-mail configurado no provedor.'],['Como solicito dados ou exclusão?','Entre no Perfil e registre uma solicitação. Ela será analisada pela administração; histórico sujeito a retenção não é apagado automaticamente.']] : [['Como faço um pedido?','Escolha uma loja aberta, consulte um produto, selecione adicionais e quantidade e adicione ao carrinho. Cada pedido pertence a uma única loja.'],['Os pedidos são enviados de verdade?','Não nesta versão. Contas, pedidos, avaliações e conversas são demonstrações armazenadas neste navegador.'],['Quem faz a entrega?','Cada estabelecimento é responsável pela própria entrega. O NortFood não possui entregadores.'],['Posso retirar na loja?','Sim, quando a loja habilitar retirada e cadastrar seu endereço. Escolha Retirada na revisão do pedido.'],['Como acompanho ou cancelo?','Abra Pedidos e Ver detalhes. O estado depende da atualização local pelo estabelecimento. O cliente pode cancelar enquanto o pedido estiver Recebido.'],['Como pago?','Escolha uma opção aceita pela loja para pagamento na entrega ou retirada. A plataforma não processa nem confirma pagamentos.'],['Como falo com a loja?','Use Sobre no perfil da loja ou Conversar no detalhe do pedido. Conversas ficam neste navegador. O telefone só aparece quando cadastrado.'],['Como funciona meu endereço?','No Perfil, abra Endereços. Você pode cadastrar manualmente ou usar o mapa. A localização é opcional e depende da sua permissão.'],['Como proteger minha conta?','Não use credenciais reais. A senha é derivada localmente, mas este protótipo exige backend para autenticação e autorização seguras.'],['Como o estabelecimento gerencia pedidos?','Entre com uma conta de estabelecimento, configure seu perfil e cardápio e atualize pedidos no painel. Os dados não são sincronizados entre dispositivos.']];return '<main class="wrap help-page">'+pageHeading('Central de ajuda','Primeiros passos e respostas sobre o NortFood.','home')+'<label class="field">Pesquisar ajuda<input id="help-search" placeholder="Pedido, pagamento, endereço…"></label><div id="faq-list">'+faq.map(([q,a])=>'<details class="faq-item"><summary>'+q+'</summary><p>'+a+'</p></details>').join('')+'</div><p id="faq-empty" hidden>Nenhuma resposta encontrada.</p><button class="btn soft" data-view="privacy">Privacidade</button></main>'+footer()}
function routeSnapshot(){return {view,storeId,shopTab,selectedOrder,tab,query,filter,searchKind,sortMode,onlyOpen,orderScope}}
function routeHash(state){return '#'+state.view+(state.view==='shop'?'/'+encodeURIComponent(state.storeId):state.view==='order-detail'?'/'+encodeURIComponent(state.selectedOrder):'')}
function syncRoute(){if(restoringRoute||view==='address')return;const state=routeSnapshot(),key=JSON.stringify(state);if(key===lastRoute)return;lastRoute=key;const previous=window.history.state?.nortfood;const samePage=previous?.view===view&&(view!=='shop'||previous.storeId===storeId)&&(view!=='order-detail'||previous.selectedOrder===selectedOrder);window.history[samePage?'replaceState':'pushState']({nortfood:state},'',routeHash(state))}
function restoreRoute(state){restoringRoute=true;view=state.view||'home';if(!['home','search','favorites','offers','help','addresses','order-detail','shop','address','profile','seller','seller-settings','conversations','notifications','settings','legal','privacy','map','orders','admin','not-found'].includes(view))view='not-found';storeId=state.storeId||'';shopTab=state.shopTab||'menu';selectedOrder=state.selectedOrder||'';tab=state.tab||'orders';query=state.query||'';filter=state.filter||'Todos';searchKind=state.searchKind||'stores';sortMode=state.sortMode||'featured';onlyOpen=!!state.onlyOpen;orderScope=state.orderScope||'all';if(['profile','orders','settings','addresses','conversations','notifications','order-detail','seller','seller-settings'].includes(view)&&!data.current)view='home';if(view==='admin'&&data.current?.role!=='admin')view='home';if(['seller','seller-settings'].includes(view)&&data.current?.role!=='seller')view='home';lastRoute=JSON.stringify(routeSnapshot());render();restoringRoute=false;window.history.replaceState({nortfood:routeSnapshot()},'',routeHash(routeSnapshot()))}
window.addEventListener('popstate',e=>{const parts=location.hash.slice(1).split('/');restoreRoute(e.state?.nortfood||{view:parts[0],storeId:parts[0]==='shop'?routeDecode(parts[1]||''):'',selectedOrder:parts[0]==='order-detail'?routeDecode(parts[1]||''):''})});
window.addEventListener('hashchange',()=>{const parts=location.hash.slice(1).split('/'),target=parts[0]||'home';if(view===target&&(target!=='shop'||storeId===routeDecode(parts[1]||''))&&(target!=='order-detail'||selectedOrder===routeDecode(parts[1]||'')))return;restoreRoute({view:target,storeId:target==='shop'?routeDecode(parts[1]||''):'',selectedOrder:target==='order-detail'?routeDecode(parts[1]||''):''});window.history.replaceState({nortfood:routeSnapshot()},'',location.hash)});
function extraClick(t,e){if(t.dataset.orderSound!==undefined){if(!window.AudioContext&&!window.webkitAudioContext)return toast('Este navegador não oferece alerta sonoro.');orderAudioEnabled=!orderAudioEnabled;if(orderAudioEnabled){orderAudio||=new (window.AudioContext||window.webkitAudioContext)();orderAudio.resume();playOrderAlert()}render();return true}if(t.dataset.pauseBanner!==undefined){bannerPaused=!bannerPaused;render();return true}if(t.dataset.shareStore!==undefined){const url=new URL(location.href);url.searchParams.delete('mesa');url.hash='shop/'+encodeURIComponent(storeId);modal('<div class="modal-head"><h2>Link do estabelecimento</h2><button class="close" data-action="close-modal">×</button></div><p>Copie o link para compartilhar. Em um servidor local, ele funciona apenas neste dispositivo.</p><input aria-label="Link da loja" readonly value="'+esc(url.href)+'">');return true}if(t.dataset.recentSearch){query=t.dataset.recentSearch;render();return true}if(t.dataset.product){rememberStore(t.dataset.product);productDetail(t.dataset.product,Number(t.dataset.index));return true}if(t.dataset.productFav){toggleFavorite(t.dataset.productFav,'products');return true}if(t.dataset.shopTab){shopTab=t.dataset.shopTab;render();return true}if(t.dataset.searchKind){searchKind=t.dataset.searchKind;render();return true}if(t.dataset.orderScope){orderScope=t.dataset.orderScope;render();return true}if(t.dataset.orderDetail){selectedOrder=t.dataset.orderDetail;view='order-detail';render();return true}if(t.dataset.reviewOrder){reviewOrder(t.dataset.reviewOrder);return true}if(t.dataset.replaceCart!==undefined){if(!pendingProduct)return true;const p=pendingProduct;pendingProduct=null;const previous=data.cart;data.cart=[];closeModal();if(addProductToCart(p.store,p.index,p.extras,p.note,p.quantity)!==true){data.cart=previous;save()}return true}if(t.dataset.newAddress!==undefined){manualAddress();return true}if(t.dataset.editAddress){manualAddress(t.dataset.editAddress);return true}if(t.dataset.addressMap!==undefined){editingAddress='';addressForCheckout=addressCheckout;openAddressPicker(addressCheckout);return true}if(t.dataset.selectAddress){const a=addresses().find(x=>x.id===t.dataset.selectAddress);if(a){applyAddress(a);save();if(addressCheckout)showCheckoutPayment();else render()}return true}if(t.dataset.chatStore){if(!data.current){auth();return true}if(data.current.role!=='customer'){view='conversations';render();return true}const s=data.stores.find(x=>x.id===t.dataset.chatStore);if(!s)return true;let c=data.conversations.find(x=>x.storeId===s.id&&x.email===data.current.email);if(!c){data.conversations.push({id:'chat-'+Date.now(),storeId:s.id,email:data.current.email,customer:data.current.name,messages:[],updated:Date.now()});save()}view='conversations';render();return true}if(t.dataset.fulfillment){fulfillment=t.dataset.fulfillment;closeModal();if(fulfillment==='pickup')showCheckoutPayment();else{view='addresses';addressCheckout=true;render()}return true}return false}
function extraSubmit(f,d){if(f.id==='manual-address-form'){if(data.current?.role!=='customer')return true;const a={id:editingAddress||'a-'+Date.now(),label:String(d.get('label')||'').trim(),street:String(d.get('street')||'').trim(),number:String(d.get('number')||'').trim(),complement:String(d.get('complement')||'').trim(),reference:String(d.get('reference')||'').trim()};if(!a.label||!a.street||!a.number){toast('Informe nome, rua e número.');return true}a.formatted=a.street+', '+a.number+(a.complement?' - '+a.complement:'')+', Porteirinha, MG';const list=addresses(),i=list.findIndex(x=>x.id===a.id);if(i>=0)list[i]=a;else list.push(a);applyAddress(a);save();closeModal();if(addressCheckout)showCheckoutPayment();else{view='addresses';render()}toast('Endereço salvo neste navegador.');return true}if(f.id==='review-form'){const o=accessibleOrder(f.dataset.order),rating=Number(d.get('rating')),text=String(d.get('text')||'').trim();if(!o||data.current?.role!=='customer'||o.status!=='Entregue'||!Number.isInteger(rating)||rating<1||rating>5||!text){toast('Confira a avaliação e o pedido.');return true}const existing=data.reviews.find(x=>x.order===o.id),r={order:o.id,store:o.store,email:o.email,customer:data.current.name,rating,text:text.slice(0,500),created:Date.now()};if(existing)Object.assign(existing,r);else data.reviews.push(r);save();render();toast('Avaliação salva localmente.');return true}return false}
document.addEventListener('change',e=>{if(e.target.matches('[data-option-price],#product-quantity'))updateProductTotal();if(e.target.matches('[data-discovery-sort]')){sortMode=e.target.value;render()}if(e.target.matches('[data-only-open]')){onlyOpen=e.target.checked;render()}if(e.target.matches('[data-discovery-category]')){filter=cats.find(category=>category.id===e.target.value)?.label||'Todos';render()}});
