let overlayFocus=null;
function focusOverlay(){overlayFocus=document.activeElement;const panel=document.querySelector('.modal,.drawer');if(!panel)return;panel.querySelectorAll('.close:not([aria-label])').forEach(button=>button.setAttribute('aria-label','Fechar'));panel.setAttribute('role','dialog');panel.setAttribute('aria-modal','true');panel.setAttribute('aria-label',panel.querySelector('h2')?.textContent||'NortFood');panel.querySelector('input:not([type=checkbox]),select,button')?.focus()}
document.addEventListener('keydown',e=>{if(e.key==='Enter'&&e.target.id==='search'){rememberSearch();view='search';render();document.getElementById('search')?.focus();return}const panel=document.querySelector('.modal,.drawer');if(!panel){if(e.key==='Enter'&&e.target.matches('.store-card')){storeId=e.target.dataset.open;shopTab='menu';view='shop';render()}return}if(e.key==='Escape'){closeModal();closeCart();overlayFocus?.focus();return}if(e.key==='Tab'){const controls=[...panel.querySelectorAll('button:not([disabled]),input:not([disabled]),select,textarea,a[href]')].filter(x=>x.getClientRects().length);const first=controls[0],last=controls.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus()}}});
async function derivePassword(password,salt){if(!globalThis.crypto?.subtle)throw new Error('Use localhost ou HTTPS para acessar contas.');const material=await crypto.subtle.importKey('raw',new TextEncoder().encode(password),'PBKDF2',false,['deriveBits']);const bits=await crypto.subtle.deriveBits({name:'PBKDF2',hash:'SHA-256',iterations:120000,salt:new TextEncoder().encode(salt)},material,256);return Array.from(new Uint8Array(bits),b=>b.toString(16).padStart(2,'0')).join('')}
async function setPassword(u,password){const salt=Array.from(crypto.getRandomValues(new Uint8Array(16)),b=>b.toString(16).padStart(2,'0')).join('');u.passwordHash=await derivePassword(password,salt);u.passwordSalt=salt;delete u.password}
async function checkPassword(u,password){return !!u.passwordHash&&await derivePassword(password,u.passwordSalt)===u.passwordHash}
async function protectExistingPasswords(){for(const u of data.users)if(u.password!==undefined)await setPassword(u,String(u.password));save()}


window.addEventListener('online',()=>{if(commercial)commercialController?.refresh('POLL')});window.addEventListener('offline',()=>{if(commercial){connectionStatus='error';connectionMessage='Sem conexão. Operações precisam de confirmação do servidor.';const banner=document.querySelector('.connection-banner');if(banner){banner.textContent=connectionMessage;banner.classList.add('error')}}});
function commercialBanner(){return '<div class="wrap"><p class="connection-banner '+(connectionStatus==='error'?'error':'')+'" role="status">'+esc(connectionStatus==='connected'?(connectionMessage||'Conectado ao servidor · mantenha o painel aberto durante a operação'):connectionStatus==='loading'?'Conectando ao servidor…':connectionMessage||'Configuração Supabase pendente. Pedidos comerciais bloqueados.')+'</p></div>'}
function commercialDeliveryFee(s){if(!s||s.deliveryEnabled===false)return null;const a=addresses().find(a=>a.formatted===data.current?.address);if(!a)return null;const norm=value=>String(value??'').trim().toLocaleLowerCase('pt-BR'),zone=(s.deliveryZones||[]).find(z=>z.active!==false&&norm(z.neighborhood)===norm(a.neighborhood)&&norm(z.city)===norm(a.city)&&String(z.state||'MG')===String(a.state||'MG'));return zone&&Number.isInteger(zone.fee_cents)&&zone.fee_cents>=0?zone.fee_cents/100:null;}
function deliveryFeeLabel(s){const fee=storeDeliveryFee(s);return fee!==null?money(fee):s?.deliveryEnabled===false?'Entrega indisponível':data.current?.address?'Endereço fora da área atendida':'Confirme o endereço para calcular';}
function commercialSellerOrders(os){const states=['all','Recebido','Aceito','Em preparo','Pronto para entrega','Pronto para retirada','Em entrega','Entregue','Retirado','Pronto para servir','Servido','Cancelado','Recusado'];return '<div class="filters">'+states.map(status=>'<button class="pill '+(sellerOrderFilter===status?'active':'')+'" data-order-filter="'+esc(status)+'">'+(status==='all'?'Todos':status)+'</button>').join('')+'</div>'+os.filter(o=>sellerOrderFilter==='all'||o.status===sellerOrderFilter).map(o=>'<section class="dash-card"><div class="dash-card-body">'+history(o,false)+'<p>Cliente: '+esc(o.customer)+(o.customerPhone?' · Telefone: '+esc(o.customerPhone):'')+'</p>'+orderItems(o.items)+'<p>'+esc(o.notes)+'</p><div class="detail-actions">'+commercialController.orderActions(o)+'</div></div></section>').join('')}
function commercialSales(os){const complete=os.filter(o=>['Entregue','Retirado','Servido'].includes(o.status)),total=complete.reduce((n,o)=>n+o.raw.subtotal_cents,0);return '<section class="dash-card"><div class="dash-card-body"><h2>Vendas concluídas na lista carregada</h2><p>'+complete.length+' pedidos · '+money(total/100)+' em produtos.</p><p>Valores não incluem taxa de entrega. Histórico mostra os valores originais.</p>'+complete.map(o=>history(o,false)).join('')+'</div></section>'}
function prepareStoreLocation(){const form=document.getElementById('store-form'),s=data.stores.find(s=>s.id===data.current?.storeId);if(form&&s&&!form.querySelector('[data-location-editor]')){const submit=form.querySelector('button:not([type]),button[type=submit]');submit.insertAdjacentHTML('beforebegin',window.NortFoodLocation.editor(s));submit.textContent='Salvar perfil e localização';}window.NortFoodLocation?.mount(document);}
