 const passwordForm=document.getElementById('password-form');if(passwordForm){const old=passwordForm.elements.currentPassword;if(old){old.required=false;old.parentElement.hidden=true}passwordForm.elements.newPassword.minLength=12;passwordForm.elements.confirmPassword.minLength=12;}
 const storeForm=document.getElementById('store-form');if(storeForm){for(const field of ['pixKey','deliveryFee','time']){const input=storeForm.elements[field];if(input){input.disabled=true;input.parentElement.hidden=true}}}
 const auth=document.getElementById('auth-form');if(auth){auth.elements.password.minLength=authMode==='register'?12:1;auth.elements.identifier.type='email';auth.elements.identifier.placeholder='voce@exemplo.com';const emailLabel=auth.querySelector('label[for=auth-email]');if(emailLabel)emailLabel.textContent='E-mail';document.querySelector('.auth-demo-note').textContent='Acesso pelo provedor Supabase. Contas locais de demonstração não são contas comerciais.';const google=auth.closest('.modal').querySelector('[data-action="google-auth"]'),note=auth.closest('.modal').querySelector('#google-unavailable');if(google&&note){note.textContent='Verificando disponibilidade do Google…';Promise.resolve(window.NortFoodBackend?.googleAvailable?.()??false).then(available=>{if(!google.isConnected)return;google.disabled=available!==true;note.textContent=available===true?'Acesso seguro pelo Google.':available===false?'Login com Google não configurado neste ambiente.':'Não foi possível verificar o Google. Tente novamente mais tarde.';});}const forgot=document.querySelector('.auth-unavailable');if(forgot)forgot.outerHTML='<button type="button" class="text-btn" data-action="recover-password">Recuperar acesso</button>'}
 const pf=document.getElementById('product-options');if(pf){const store=data.stores.find(s=>s.id===pf.dataset.store),p=store?.products[Number(pf.dataset.index)];if(p?.[10]?.length){pf.querySelector('fieldset')?.insertAdjacentHTML('afterbegin','<p class="section-sub">'+p[10].map(g=>esc(g.name)+': de '+g.min_choices+' a '+g.max_choices+' escolha(s)').join('<br>')+'</p>')}}document.querySelectorAll('#manual-address-form,#delivery-address-form').forEach(form=>{if(!form.elements.neighborhood)form.querySelector('button.btn').insertAdjacentHTML('beforebegin','<div class="field"><label for="address-neighborhood">Bairro</label><input id="address-neighborhood" name="neighborhood" required maxlength="80" value="'+esc(addresses().find(a=>a.id===editingAddress)?.neighborhood||'')+'"></div>')});
